/**
 * @brief 清理运行资源，加载目标场景及实例，恢复显示和音乐
 *
 * @note 保存并清零 VBlank 模式与场景 BGM，按入口图块坐标设置玩家（可选相机）位置，
 *       清精灵与传输状态后重载场景、Actor、宝箱和装饰动画资源，恢复 VBlank 模式并
 *       按脚本标志决定是否启动开场脚本与过渡；最后按 BGM 变化选择恢复或重播音乐。
 * @address 0x08001354
 */
void Scene_EnterMap(void)
{
    u16 entry;
    u8 savedVBlankMode;
    s32 savedBgmId;

    System_SuspendAudioAndBlankDisplay();
    savedVBlankMode = gVBlankUpdateMode;
    gVBlankUpdateMode = 0;
    savedBgmId = gSceneBgmId;
    gBg1RasterMode = 0;
    Palette_DisableAnimations();
    gPlayerX = gSceneEntryTileX << 3;
    gPlayerY = gSceneEntryTileY << 3;
    if (gCameraFollowDisabled != 0)
    {
        gCameraX = gPlayerX;
        gCameraY = gPlayerY;
    }
    Sprite_ClearNodes();
    Sprite_ClearAffineMatrices();
    Sprite_ClearDrawOrder();
    for (entry = 0; entry < CORE_SPRITE_OAM_COUNT; entry++)
    {
        gSpriteOamBuffer[entry].words[0] = 0;
        gSpriteOamBuffer[entry].words[1] = 0;
    }
    Sprite_ClearTileTransfers();
    Sprite_ClearPaletteTransfers();
    MapAnimation_DisableAll();
    FieldAnim_DisableAll();
    Actor_FreeAllSprites();
    gPlayerDirection = gSceneEntryDirection;
    Player_InitActors();
    Player_UpdateActors();
    Scene_LoadResources(gPendingSceneId);
    Actor_LoadSceneResources(gPendingSceneId);
    Actor_InitScene(gPendingSceneId);
    Camera_SetBounds(gSceneCameraRegionId);
    Chest_InitScene(gPendingSceneId);
    FieldAnim_LoadResources(gFieldAnimationGroupId);
    FieldAnim_InitInstances(gFieldAnimationGroupId);
    gVBlankUpdateMode = savedVBlankMode;
    if ((Script_GetFlags() & 1) == 0)
    {
        Script_Start(0xFF, 2);
        Script_Update();
    }
    Scene_UpdateFrame();
    *(vu16 *)REG_WIN0H = 0xF0;
    *(vu16 *)REG_WIN0V = 0xA0;
    (*(vu16 *)REG_DISPCNT) |= 0x2000;
    *(vu16 *)REG_WININ = 0;
    *(vu16 *)REG_WINOUT = 0;
    if ((Script_GetFlags() & 1) == 0)
    {
        Palette_SaveTransitionSource();
        Transition_Start(3);
    }
    gFieldInputDelay = 2;
    gSceneState = 1;
    gScenePhase = 0;
    System_ResumeAudioAndDisplay();
    if (gSceneBgmControl == 0xFF && gSceneBgmId != 0)
    {
        if (savedBgmId == gSceneBgmId)
        {
            Sound_SetBgmVolume(0);
            System_WaitVisibleFrameAndUpdateSound();
            Sound_ResumeBgm();
            System_WaitVisibleFrameAndUpdateSound();
            Sound_FadeInBgm(4);
        }
        else
        {
            Sound_SetBgmVolume(0);
            System_WaitVisibleFrameAndUpdateSound();
            Sound_StopBgm();
            System_WaitVisibleFrameAndUpdateSound();
            Sound_PlayBgm(gSceneBgmId, 0);
            System_WaitVisibleFrameAndUpdateSound();
            Sound_FadeInBgm(4);
        }
    }
}

/**
 * @brief 初始化新游戏的持久状态、队伍和开场脚本
 *
 * @note 清零场景阶段、过渡计数、入口坐标与相机区域等持久状态，设置 VBlank 模式和
 *       待启动场景编号；清空队伍成员槽并置位其余槽，初始化队伍与背包后为全部角色
 *       计算并应用初始装备加成，设置金钱与游戏时间并放置玩家。配置窗口后按标题演示
 *       阶段选择脚本银行与等待帧数，最后启动开场脚本并进入状态 1。
 * @address 0x08001538
 */
void Scene_StartNewGame(void)
{
    u8 characterId;
    u16 i;

    gSceneBgmControl = 0xFF;
    gSceneScriptRunningSnapshot = 0;
    gCoreUnknown0000 = 0;
    gCoreUnknown0002 = 0;
    gScenePhase = 0;
    gSceneTransitionCounter = 0;
    gCoreUnknown2608 = 0;
    gPlayerFieldFlags = 0;
    gPlayerTransitionStage = 0;
    gVisitedDestination[0] = 0;
    gVisitedDestination[1] = 0;
    gVBlankUpdateMode = 1;
    gPendingSceneId = 0x82;
    gSceneEntryTileX = 0;
    gSceneEntryTileY = 0;
    gSceneEntryDirection = 0;
    gSceneCameraRegionId = 0;
    gPartyMembers[0] = 0;
    gPartyMembers[1] |= 0xFF;
    gPartyMembers[2] |= 0xFF;
    gPartyMembers[3] |= 0xFF;
    gPartyMembers[4] |= 0xFF;
    gPartyMembers[5] |= 0xFF;
    gPartyCharacterSlots[0] = 0;
    gPartyCharacterSlots[1] |= 0xFF;
    gPartyCharacterSlots[2] |= 0xFF;
    gPartyCharacterSlots[3] |= 0xFF;
    gPartyCharacterSlots[4] |= 0xFF;
    gPartyCharacterSlots[5] |= 0xFF;
    Party_InitCharactersAndInventory();
    for (characterId = 0; characterId <= 10; characterId++)
    {
        Party_CalculateEquipmentBonuses(characterId);
        Party_ApplyEquipmentBonuses(characterId);
    }
    gPartyItemCounts[0xDD] = 2;
    gPartyGold = 300;
    gPlayTimeFrames = 0;
    gPlayerX = 0x60;
    gPlayerY = 0x50;
    Script_Init();
    *(vu16 *)REG_WIN0H = 0xF0;
    *(vu16 *)REG_WIN0V = 0xA0;
    (*(vu16 *)REG_DISPCNT) |= 0x2000;
    *(vu16 *)REG_WININ = 0;
    *(vu16 *)REG_WINOUT = 0;
    if (gTitlePresentationStage == 0)
    {
        gSceneScriptBankId = 1;
        gSavedSceneScriptBankId = 1;
        Script_LoadBank(1, 0, 1);
        for (i = 0; i < 16; i++)
            System_WaitVisibleFrameAndUpdateSound();
    }
    else
    {
        Script_LoadBank(0, 0, 1);
        for (i = 0; i < 4; i++)
            System_WaitVisibleFrameAndUpdateSound();
    }
    Script_Start(1, 2);
    gSceneState = 1;
    gScenePhase = 0;
}

/**
 * @brief 在同一地图内重设玩家位置、朝向、相机和跟随历史
 *
 * @note 过渡类型为零且阶段为 1 时，按入口图块坐标重设玩家（可选相机）位置与朝向，
 *       重载角色并刷新八项位置历史，再把 Actor 1 同步到 Actor 0；随后进入状态 1。
 *       否则按既有转场阶段递增计数器并启动过场。两条路径最后都更新一帧。
 * @address 0x08001708
 */
void Scene_RepositionPlayer(void)
{
    u16 i;

    if (gScreenTransitionType == 0 && gScenePhase == 1)
    {
        gPlayerX = gSceneEntryTileX << 3;
        gPlayerY = gSceneEntryTileY << 3;
        if (gCameraFollowDisabled != 0)
        {
            gCameraX = gPlayerX;
            gCameraY = gPlayerY;
        }
        Camera_SetBounds(gSceneCameraRegionId);
        gPlayerDirection = gSceneEntryDirection;
        Player_UpdateActors();
        for (i = 0; i < CORE_PLAYER_HISTORY_COUNT; i++)
        {
            gPlayerPositionHistoryX[i] = gActorStates[0].x;
            gPlayerPositionHistoryY[i] = gActorStates[0].y;
            gPlayerPositionHistoryDirection[i] = gActorStates[0].direction;
        }
        gActorStates[1].x = gActorStates[0].x;
        gActorStates[1].y = gActorStates[0].y;
        gActorStates[1].direction = gActorStates[0].direction;
        Transition_Start(3);
        gFieldInputDelay = 2;
        gSceneState = 1;
        gScenePhase = 0;
    }
    else
    {
        if (gScenePhase != 1)
        {
            gSceneTransitionCounter = (gSceneTransitionCounter + 1) & 1;
            gScenePhase = 1;
            Palette_SaveTransitionSource();
            Transition_Start(4);
        }
    }
    Scene_UpdateFrame();
}

/**
 * @brief 等待淡出，准备遭遇并切到战斗主循环
 *
 * @note 首次启动转场；阶段 1 且转场完成后准备战斗，遭遇编号按 s8 传递。
 * @address 0x08001828
 */
void Scene_EnterBattle(void)
{
    // u8 transitionType = gScreenTransitionType;

    if (gScreenTransitionType == 0 && gScenePhase == 1)
    {
        System_SuspendAudioAndBlankDisplay();
        gVBlankUpdateMode = 0;
        gScenePhase = 0;
        if (gScriptedBattleState != 0)
        {
            gScriptedBattleState++;
            Battle_PrepareEncounter((s8)gScriptedEncounterId);
        }
        else
            Battle_PrepareEncounter((s8)gSceneEncounterConfigId);
        gGameLoopMode = 1;
        gVBlankUpdateMode = 2;
    }
    else
    {
        if (gScenePhase != 1)
        {
            gScenePhase = 1;
            Palette_SaveTransitionSource();
            Transition_Start(4);
            Sound_PlaySfx(22, 0, 0);
            Sound_FadeOutBgm(46);
        }
        Scene_UpdateFrame();
    }
}

/**
 * @brief 恢复场景资源或轻量显示状态，回到场景循环
 *
 * @note 先关闭中断、禁用调色板动画并清空软件 OAM 与传输槽。脚本战斗状态非零时递增
 *       并仅在返回模式 2 走轻量显示路径；否则重载场景、脚本银行、Actor 资源、相机
 *       边界和装饰动画，按脚本标志与返回模式决定是否启动过渡，最后按 BGM 编号恢复
 *       音乐并更新一帧。
 * @address 0x080018D4
 */
void Scene_ReturnFromBattle(void)
{
    s16 entry;

    (*(vu16 *)REG_IME) = 0;
    Palette_DisableAnimations();
    gVBlankUpdateMode = 0;
    Sprite_ClearDrawOrder();
    for (entry = 0; entry <= 0x7F; entry++)
    {
        gSpriteOamBuffer[entry].words[0] = 0;
        gSpriteOamBuffer[entry].words[1] = 0;
    }
    Sprite_ClearTileTransfers();
    Sprite_ClearPaletteTransfers();
    if (gScriptedBattleState != 0)
    {
        gScriptedBattleState++;
        if (gBattleFieldReturnMode == 2)
        {
            Palette_LoadDefaultBackdropColor();
            *(vu16 *)REG_WIN0H = 0xF0;
            *(vu16 *)REG_WIN0V = 0xA0;
            (*(vu16 *)REG_DISPCNT) |= 0x2000;
            *(vu16 *)REG_WININ = 0;
            *(vu16 *)REG_WINOUT = 0;
            gVBlankUpdateMode = 1;
            gSceneState = 1;
            gScenePhase = 0;
            (*(vu16 *)REG_IME) = 1;
            System_ResumeAudioAndDisplay();
            return;
        }
    }

    Player_UpdateActors();
    gVBlankUpdateMode = 1;
    (*(vu16 *)REG_IME) = 1;
    Scene_LoadResources(gPendingSceneId);
    if ((Script_GetFlags() & 1) == 0)
        Script_LoadBank(gSavedSceneScriptBankId, 0, 1);
    Actor_ReloadResources();
    Camera_SetBounds(gSceneCameraRegionId);
    FieldAnim_LoadResources(gFieldAnimationGroupId);
    gSceneState = 1;
    gScenePhase = 0;
    *(vu16 *)REG_WIN0H = 0xF0;
    *(vu16 *)REG_WIN0V = 0xA0;
    (*(vu16 *)REG_DISPCNT) |= 0x2000;
    *(vu16 *)REG_WININ = 0;
    *(vu16 *)REG_WINOUT = 0;
    if (gScriptedBattleState == 0 || gBattleFieldReturnMode != 1)
    {
        Palette_SaveTransitionSource();
        Transition_Start(3);
    }
    System_ResumeAudioAndDisplay();
    if (gSceneBgmId != 0)
    {
        System_WaitVisibleFrameAndUpdateSound();
        Sound_PlayBgm(gSceneBgmId, 0);
        System_WaitVisibleFrameAndUpdateSound();
        Sound_FadeInBgm(4);
    }
    Scene_UpdateFrame();
}

/**
 * @brief 加载世界地图、玩家资源和地点选择状态
 *
 * @note 首次启动转场；过渡完成后重建世界地图资源和玩家 Actor，清相机原点并冻结
 *       跟随历史，按连接编号选择地点，同步玩家与跟随者坐标，最后选择世界地图 BGM。
 * @address 0x08001A7C
 */
void Scene_EnterWorldMap(void)
{
    u8 bgmId;

    if (gScreenTransitionType == 0 && gScenePhase == 1)
    {
        System_SuspendAudioAndBlankDisplay();
        Palette_DisableAnimations();
        Sprite_ClearNodes();
        Sprite_ClearAffineMatrices();
        Sprite_ClearDrawOrder();
        WorldMap_LoadResources(gWorldMapRegionId);
        WorldMap_LoadPlayerResources();
        Player_InitActors();
        gCameraX = 0;
        gCameraY = 0;
        gPlayerDirection = 4;
        Palette_SaveTransitionSource();
        Transition_Start(3);
        gScenePhase = 0;
        gSceneState = 9;
        Player_FreezePositionHistory();
        WorldMap_LoadConnections();
        WorldMap_SelectLocation(gWorldMapConnectionIds[gWorldMapConnectionIndex] & 0xF);
        gPlayerX = gWorldMapTargetX;
        gPlayerY = gWorldMapTargetY;
        gActorStates[1].x = gWorldMapTargetX;
        gActorStates[1].y = gWorldMapTargetY - 8;
        gActorStates[1].stateFlags |= 0x10;
        gActorStates[1].direction = 4;
        WorldMap_DrawMarkers();
        System_ResumeAudioAndDisplay();
        gSceneBgmId = 0;
        if (EventFlags_GetMask(0x39))
            bgmId = 6;
        else
            bgmId = 5;
        System_WaitVisibleFrameAndUpdateSound();
        Sound_PlayBgm(bgmId, 0);
        System_WaitVisibleFrameAndUpdateSound();
        Sound_FadeInBgm(4);
    }
    else
    {
        if (gScenePhase != 1)
        {
            gSceneTransitionCounter = (gSceneTransitionCounter + 1) & 1;
            gScenePhase = 1;
            Palette_SaveTransitionSource();
            Transition_Start(4);
            Sound_FadeOutBgm(46);
        }
        Scene_UpdateFrame();
    }
}

/**
 * @brief 从既有EWRAM快照恢复精灵和仿射状态，再重载场景资源
 *
 * @note 禁用调色板动画并清空软件 OAM、传输槽与地图／装饰动画后初始化脚本服务，
 *       清玩家过渡阶段与相机跟随禁用位，把场景 BGM 控制置 0xFF；随后用 DMA3 分
 *       别从节点和仿射快照恢复精灵池，重载玩家历史和场景资源，进入状态 1 并启动
 *       过渡；场景 BGM 编号非零时先播放、更新一帧并淡入，最后再更新一帧。
 * @address 0x08001BD0
 */
void Scene_RestoreFieldSnapshot(void)
{
    s16 entry;

    Palette_DisableAnimations();
    Sprite_ClearDrawOrder();
    for (entry = 0; entry <= 0x7F; entry++)
    {
        gSpriteOamBuffer[entry].words[0] = 0;
        gSpriteOamBuffer[entry].words[1] = 0;
    }
    Sprite_ClearTileTransfers();
    Sprite_ClearPaletteTransfers();
    MapAnimation_DisableAll();
    FieldAnim_DisableAll();
    Script_Init();
    gPlayerTransitionStage = 0;
    gCameraFollowDisabled = 0;
    gSceneBgmControl = 0xFF;
    DmaCopy(3, SPRITE_NODE_SNAPSHOT, gSpriteNodes, sizeof(gSpriteNodes), 16);
    DmaCopy(3, SPRITE_AFFINE_SNAPSHOT, gSpriteAffineMatrices, sizeof(gSpriteAffineMatrices), 16);
    Player_UpdateActors();
    Player_ResetPositionHistory();
    Scene_LoadResources(gPendingSceneId);
    Script_LoadBank(gSavedSceneScriptBankId, 0, 1);
    Actor_ReloadResources();
    Camera_SetBounds(gSceneCameraRegionId);
    FieldAnim_LoadResources(gFieldAnimationGroupId);
    FieldAnim_InitInstances(gFieldAnimationGroupId);
    gSceneState = 1;
    gScenePhase = 0;
    Palette_SaveTransitionSource();
    Transition_Start(3);
    gFieldInputDelay = 2;
    System_ResumeAudioAndDisplay();
    if (gSceneBgmId != 0)
    {
        Sound_PlayBgm(gSceneBgmId, 0);
        Scene_UpdateFrame();
        System_WaitVisibleFrameAndUpdateSound();
        Sound_FadeInBgm(4);
    }
    Scene_UpdateFrame();
}

/**
 * @brief 处理场景输入、交互、脚本、遇敌和玩家过渡演出
 *
 * @address 0x08001D08
 */
void Scene_UpdateField(void)
{
    u8 keyMask = 0;
    u8 entryId;
    u8 speed;

    gActorStates[0].stateFlags &= ~0x40;
    if (!(Script_GetFlags() & 1))
    {
        gSceneScriptRunningSnapshot = 0;
        if (gTitlePresentationStage != 0 && !(gScanlineBlendFlags & 0x80) && gScreenTransitionType == 0)
        {
            gSceneState = 11;
            gScenePhase = 5;
            return;
        }
    }
    else
    {
        gSceneScriptRunningSnapshot = 1;
        if (gTitlePresentationStage != 0 && !(gScanlineBlendFlags & 0x80) && gScreenTransitionType == 0
            && (gKeysPressed & 0x30F) != 0)
        {
            Script_Stop(1);
            gSceneState = 11;
            gScenePhase = 5;
            return;
        }
    }
    if ((gKeysHeld & 15) == 15)
    {
        Script_Stop(1);
        System_RequestTitle();
        return;
    }
    if (gMenuState == 0 && gPlayerTransitionStage == 0)
    {
    if (gSceneScriptRunningSnapshot == 0
        && !(gScanlineBlendFlags & 0x80) && gScreenTransitionType == 0)
    {
        if (gFieldInputDelay != 0)
        {
            gFieldInputDelay--;
            gKeysPressed = 0;
            gKeysHeld = 0;
        }
        if (gPendingSceneScriptEntryId != 255)
        {
            Script_Start(gPendingSceneScriptEntryId, 2);
            gPendingSceneScriptEntryId = 255;
        }
        else
        {
            if (gKeysPressed & 1)
            {
                entryId = Scene_Interact();
                if (entryId != 0)
                    Script_Start((u8)(entryId - 1), 2);
            }
            else if (gKeysPressed & 2)
                Menu_UpdateState();
            if (Script_GetFlags() & 1)
                gSceneScriptRunningSnapshot = 1;
            if (gSceneScriptRunningSnapshot == 0 && gMenuState == 0)
            {
                if (Encounter_CheckWalking() != 0)
                {
                    gSceneState = 5;
                    return;
                }
                if (gKeysHeld & 0x40)
                {
                    keyMask = 1;
                    gActorStates[0].stateFlags |= 0x40;
                }
                else if (gKeysHeld & 0x80)
                {
                    keyMask = 2;
                    gActorStates[0].stateFlags |= 0x40;
                }
                if (gKeysHeld & 0x20)
                {
                    keyMask |= 4;
                    gActorStates[0].stateFlags |= 0x40;
                }
                else if (gKeysHeld & 0x10)
                {
                    keyMask |= 8;
                    gActorStates[0].stateFlags |= 0x40;
                }
                if (gPlayerDirectionByKeyMask[keyMask] != 0)
                {
                    gPlayerDirection = gPlayerDirectionByKeyMask[keyMask] - 1;
                    speed = 2;
                }
                else
                    speed = 0;
            }
            else
                speed = 0;
            Player_TryMove(&gPlayerX, &gPlayerY, (u8)(gPlayerDirection + 1), speed);
        }
    }
    }
    else if (gMenuState != 0)
        Menu_UpdateState();
    else
    {
        switch (gPlayerTransitionStage)
        {
        case 1:
            gPlayerTransitionStage = 2;
            break;
        case 2:
            Actor_LoadAnimation(120, 0, 10);
            System_WaitVBlankAndUpdateSound();
            Actor_LoadAnimation(121, 1, 10);
            System_WaitVBlankAndUpdateSound();
            gPlayerTransitionStage = 3;
            break;
        case 3:
            Sound_PlaySfx(25, 0, 0);
            Actor_InitAuxiliary();
            Actor_StartCustomAnimation(18, 0);
            gPlayerTransitionStage = 4;
            break;
        case 4:
            if (Actor_FinishCustomAnimation(18) != 0)
            {
                Sound_PlaySfx(26, 0, 0);
                Actor_FreeSprites(0);
                Actor_FreeSprites(1);
                Actor_StartCustomAnimation(18, 1);
                gPlayerTransitionStage = 5;
            }
            break;
        case 5:
            if (Actor_FinishCustomAnimation(18) != 0)
            {
                gSceneState = 3;
                Actor_FreeSprites(18);
                gPlayerTransitionStage = 9;
            }
            break;
        case 6:
            Sound_PlaySfx(26, 0, 0);
            Actor_LoadAnimation(122, 0, 10);
            System_WaitVBlankAndUpdateSound();
            Actor_LoadAnimation(123, 1, 10);
            System_WaitVBlankAndUpdateSound();
            Actor_InitAuxiliary();
            Actor_StartCustomAnimation(18, 0);
            gPlayerTransitionStage = 7;
            break;
        case 7:
            if (Actor_FinishCustomAnimation(18) != 0)
            {
                Sound_PlaySfx(25, 0, 0);
                Actor_StartCustomAnimation(18, 1);
                gPlayerTransitionStage = 8;
            }
            break;
        case 8:
            if (Actor_FinishCustomAnimation(18) != 0)
            {
                gPlayerTransitionStage = 0;
                Actor_FreeSprites(18);
            }
            break;
        case 9:
            if ((gScanlineBlendFlags & 0x80) || gScreenTransitionType != 0)
                gPlayerTransitionStage = 10;
            break;
        case 10:
            if (!(gScanlineBlendFlags & 0x80) && gScreenTransitionType == 0)
                gPlayerTransitionStage = 6;
            break;
        }
    }
    if (gSceneScriptRunningSnapshot != 0)
        gActorStates[0].stateFlags |= 0x40;
    Script_Update();
    TitleLogo_Update();
    Scene_UpdateFrame();
}

/**
 * @brief 更新相机和场景动画，提交角色、阴影与宝箱并生成本帧绘制数据
 *
 * @note 场景角色更新使用槽 0..18；原始图块表场景跳过角色与宝箱提交，仍执行公共帧尾。
 * @address 0x08002154
 */
void Scene_UpdateFrame(void)
{
    u16 actorId;
    struct ActorState *actor;
    u32 sceneType;             /* Arithmetic snapshot of the halfword scene code. */
    u32 customActorFlag;

    Camera_UpdateScroll();
    MapAnimation_Update();
    Map_UpdateTilemaps(gCameraX, gCameraY);
    sceneType = gSceneType;
    if ((u16)sceneType != CORE_SCENE_TYPE_RAW_TILEMAP)
    {
        customActorFlag = CORE_SCENE_TYPE_FLAG_CUSTOM_ACTORS;
        customActorFlag &= sceneType;
        if (customActorFlag != 0 && (u16)sceneType <= CORE_SCENE_TYPE_SCRIPT_BACKGROUND)
        {
            for (actorId = 0, actor = gActorStates;
                 actorId <= CORE_AUXILIARY_ACTOR_ID; actor++, actorId++)
            {
                if (actor->spriteSlot != 0 && (actor->flags & CORE_ACTOR_FLAG_CUSTOM_ANIMATION))
                {
                    u32 byteActorId;
                    s32 renderX;
                    s32 renderHeight;

                    Actor_AdvanceSceneMovementInline(actorId, actor);
                    byteActorId = (u8)actorId;
                    Actor_UpdateAnimation((u8)byteActorId);
                    renderX = Actor_GetRenderX(actor);
                    renderHeight = (s16)Actor_GetRenderHeight(actor);
                    Sprite_QueueChain(renderX, actor->y, actor->spriteSlot, renderHeight, actor->flags);
                    Actor_ClearShadowInline(actor);
                    Actor_UpdateShadow(byteActorId);
                }
            }
        }
        else
        {
            Player_UpdateActors();
            for (actorId = CORE_COLLISION_ACTOR_FIRST, actor = &gActorStates[actorId];
                 actorId <= CORE_AUXILIARY_ACTOR_ID; actor++, actorId++)
            {
                if (actor->spriteSlot != 0)
                {
                    u32 byteActorId;

                    if (gMenuState == 0 && (gPlayerTransitionStage == 0 || gPlayerTransitionStage == 9)
                        && (actor->stateFlags & (CORE_ACTOR_STATE_COMMANDS_ACTIVE | CORE_ACTOR_STATE_NO_VISIBLE_SPRITES)) != CORE_ACTOR_STATE_NO_VISIBLE_SPRITES)
                        Actor_AdvanceSceneMovementInline(actorId, actor);
                    byteActorId = (u8)actorId;
                    Actor_UpdateAnimation((u8)byteActorId);
                    Actor_ClearShadowInline(actor);
                    if ((u8)Sprite_QueueChain(actor->x, actor->y, actor->spriteSlot, actor->verticalOffset, actor->flags) != 0)
                        actor->stateFlags |= CORE_ACTOR_STATE_NO_VISIBLE_SPRITES;
                    else
                    {
                        actor->stateFlags &= ~CORE_ACTOR_STATE_NO_VISIBLE_SPRITES;
                        Actor_UpdateShadow(byteActorId);
                    }
                }
            }
        }
        for (actorId = 0; actorId < CORE_CHEST_COUNT; actorId++)
        {
            if (gChestStates[actorId].spriteSlot != 0)
                Sprite_QueueChain(gChestStates[actorId].x, gChestStates[actorId].y, gChestStates[actorId].spriteSlot, 0, 0xFF);
        }
    }
    FieldAnim_Update();
    Sprite_BuildOamBuffer();
    Palette_Update();
}

/**
 * @brief 按隔帧调度创建或更新角色阴影，并加入精灵绘制队列
 *
 * @note 按帧计数与角色编号的奇偶匹配更新；无阴影标志会直接跳过。
 * @address 0x08002380
 */
void Actor_UpdateShadow(u8 actorId)
{
    struct ActorState *actor;
    struct SpriteNode *node;

    if ((gVBlankFrameCounter & 1) != (actorId & 1))
        return;
    actor = &gActorStates[actorId];
    if (actor->flags & CORE_ACTOR_FLAG_NO_SHADOW)
        return;
    if (actor->shadowSpriteSlot == 0)
        actor->shadowSpriteSlot = Sprite_FindFreeNode();
    node = &gSpriteNodes[actor->shadowSpriteSlot];
    if (actor->flags & CORE_ACTOR_FLAG_CUSTOM_ANIMATION)
    {
        node->attr0 = 0x4000;
        node->attr1 = 0x4000;
        node->attr2 = 0x892;
        node->xOffset = 500;
        node->yOffset = 252;
    }
    else
    {
        node->attr0 = 0x4000;
        node->attr1 = 0;
        node->attr2 = 0x892;
        node->xOffset = 0;
        node->yOffset = 250;
    }
    node->chainInfo = 1;
    node->flags = 0;
    Sprite_QueueChain(Actor_GetRenderX(actor), (s16)(actor->y - 160),
        actor->shadowSpriteSlot, -160, 0xFE);
}

/**
 * @brief 转换并裁剪精灵链，按世界Y坐标将含可见节点的链头插入绘制顺序
 *
 * @note 整条链不可见时返回 1，否则返回 0；相同Y保持已有顺序，队列满时返回值仍只表示可见性。
 * @address 0x0800243C
 */
s32 Sprite_QueueChain(s32 xInput, s32 yInput, s32 spriteSlotInput,
    s32 verticalOffsetInput, s32 flagsInput)
{
    s16 x;
    s16 y;
    u8 spriteSlot;
    s16 verticalOffset;
    u8 flags;
    struct SpriteNode *node;
    struct SpriteNode *queued;
    struct SpriteNode *displaced;
    u8 remainingNodes;
    s16 screenX;
    s16 screenY;
    s16 xOffset;
    s16 yOffset;
    s32 hasVisibleNode;
    s16 index;
    s16 nextIndex;

    x = (s16)xInput;
    y = (s16)yInput;
    spriteSlot = (u8)spriteSlotInput;
    verticalOffset = (s16)verticalOffsetInput;
    flags = (u8)flagsInput;
    hasVisibleNode = 0;

    node = &gSpriteNodes[spriteSlot];
    node->submittedX = x;
    node->submittedY = y;

    remainingNodes = node->chainInfo & CORE_SPRITE_CHAIN_COUNT_MASK;

    if (!(flags & 0x81) && (node->flags == 0 || node->flags == 2))
    {
        verticalOffset = verticalOffset + 1;
    }

    if (gSceneEffects.flags & 1)
    {
        screenX = x - (((s16)gCameraX & ~0xF) + gBg3ScrollX);
    }
    else
    {
        screenX = x - (s16)gCameraX;
    }

    if (gSceneEffects.flags & 2)
    {
        screenY = y - (((s16)gCameraY & ~0xF) + gBg3ScrollY) - (s16)(verticalOffset + 4);
    }
    else
    {
        screenY = y - (s16)gCameraY - (s16)(verticalOffset + 4);
    }

    while (remainingNodes != 0)
    {
        s32 dimensionOffset;

        gSpriteScratchWidth = ((const u8 *)gSpriteDimensions)[
            ((node->attr0 >> 11) & 0x18) + ((node->attr1 >> 13) & 6)];
        dimensionOffset = ((node->attr0 >> 11) & 0x18)
            + ((node->attr1 >> 13) & 6);
        dimensionOffset += offsetof(struct SpriteDimensions, height);
        gSpriteScratchHeight = ((const u8 *)gSpriteDimensions)[dimensionOffset];

        if (node->xOffset > 256)
        {
            xOffset = node->xOffset - 511;
        }
        else
        {
            xOffset = node->xOffset;
        }

        if (node->yOffset > 128)
        {
            yOffset = node->yOffset - 255;
        }
        else
        {
            yOffset = node->yOffset;
        }

        if (x + gSpriteScratchWidth + xOffset >= (s16)gCameraX
            && x + xOffset <= (s16)gCameraX + 240
            && y + gSpriteScratchHeight + yOffset - verticalOffset - 4 >= (s16)gCameraY
            && y + yOffset - verticalOffset - 4 <= (s16)gCameraY + 160)
        {
            node->chainInfo &= CORE_SPRITE_CHAIN_COUNT_MASK;
            node->attr0 = (node->attr0 & 0xFF00) + ((screenY + yOffset) & 0xFF);
            node->attr1 = (node->attr1 & 0xFE00) + ((screenX + xOffset) & 0x1FF);
            hasVisibleNode = 1;
        }
        else
        {
            node->chainInfo |= 0x80;
        }

        node = node->next;

        remainingNodes--;
    }

    if (hasVisibleNode != 0)
    {
        index = 0;

        while (index < CORE_SPRITE_NODE_COUNT)
        {
            queued = gSpriteDrawOrder[index];

            if (queued == NULL)
            {
                gSpriteDrawOrder[index] = &gSpriteNodes[spriteSlot];
                break;
            }

            if (queued->submittedY < y)
            {
                displaced = queued;
                gSpriteDrawOrder[index] = &gSpriteNodes[spriteSlot];

                nextIndex = index + 1;
                while (nextIndex < CORE_SPRITE_NODE_COUNT)
                {
                    queued = gSpriteDrawOrder[nextIndex];
                    gSpriteDrawOrder[nextIndex] = displaced;
                    displaced = queued;
                    if (displaced == NULL)
                        break;
                    nextIndex++;
                }

                return 0;
            }

            index++;
        }
        return 0;
    }
    return 1;
}

/* Shared standard-pose counter and OBJ updates, fully inlined into the dispatcher. */
static inline void Actor_UpdateStandardAnimationInline(struct ActorState *actor)
{
    struct SpriteNode *node;
    u16 paletteBits;
    u32 frameOffset;
    u16 tileDirection;
    u32 direction;

    u16 pauseMask = actor->stateFlags & 4;

    if (pauseMask == 0)
    {
        if (actor->waitTimer == 0)
            actor->animationCounter++;
    }
    actor->animationCounter &= 31;
    paletteBits = actor->paletteSlot;
    paletteBits <<= CORE_SPRITE_PALETTE_BANK_SHIFT;
    node = &gSpriteNodes[actor->spriteSlot];

    if (!(actor->flags & 0x7C))
    {
        node->flags = actor->animationCounter >> 3;
        frameOffset = gActorStandardAnimationTileOffsets[node->flags] * 6;
        direction = gActorDirectionFlipFlags[actor->direction];
        tileDirection = direction;
        if (direction == 3)
        {
            tileDirection = 1;
            node->attr1 |= 0x1000;
        }
        else
            node->attr1 &= 0xEFFF;
        node->attr2 = (node->attr2 & 0xC00)
            | ((tileDirection * 18 + frameOffset
                + actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0)
                & CORE_SPRITE_TILE_INDEX_MASK) | paletteBits;
        node = node->next;
        if (node == NULL)
            return;
        if (direction == 3)
            node->attr1 |= 0x1000;
        else
            node->attr1 &= 0xEFFF;
        node->attr2 = (node->attr2 & 0xC00)
            | ((tileDirection * 18 + frameOffset
                + actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA4)
                & CORE_SPRITE_TILE_INDEX_MASK) | paletteBits;
    }
    else if (!(actor->flags & 4))
    {
        if (!(actor->flags & 0x10))
        {
            if (actor->flags & 0x20)
            {
                if (actor->direction != 0)
                    node->attr2 = (node->attr2 & 0xFC00)
                        + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xB0)
                            & CORE_SPRITE_TILE_INDEX_MASK);
                else
                    node->attr2 = (node->attr2 & 0xFC00)
                        + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xC0)
                            & CORE_SPRITE_TILE_INDEX_MASK);
                node = node->next;
                node->attr2 = (node->attr2 & 0xFC00)
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0)
                        & CORE_SPRITE_TILE_INDEX_MASK);
            }
        }
        else
        {
            node->flags = actor->animationCounter >> 3;
            tileDirection = gActorDirectionFlipFlags[actor->direction];
            if (tileDirection == 1)
                node->attr1 |= 0x1000;
            else
                node->attr1 &= 0xEFFF;
            node->attr2 = (node->attr2 & 0xC00)
                | ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0)
                    & CORE_SPRITE_TILE_INDEX_MASK) | paletteBits;
        }
    }
    else
    {
        if (!(actor->flags & 8))
        {
            node->flags = 0;
            direction = (actor->animationCounter >> 3) & 3;
            tileDirection = gActorDirectionFlipFlags[actor->direction + 8];
            if (tileDirection & 1)
                frameOffset = 32;
            else
                frameOffset = gActorStandardAnimationTileOffsets[direction + 4] * 16;
            if (tileDirection & 2)
                node->attr1 |= 0x1000;
            else
                node->attr1 &= 0xEFFF;
        }
        else
        {
            node->flags = 0;
            frameOffset = (actor->animationCounter >> 3) & 3;
            frameOffset = gActorStandardAnimationTileOffsets[frameOffset] * 16;
            node->attr1 &= 0xEFFF;
        }
        node->attr2 = (node->attr2 & 0xC00)
            | ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + frameOffset + 0xA0)
                & CORE_SPRITE_TILE_INDEX_MASK) | paletteBits;
    }
}

/**
 * @brief 推进标准姿态，或转交自定义动画时间线
 *
 * @note 标准分支在等待或状态位 0x04 置位时不递增计数，但始终按模 32 截断。
 * @address 0x0800271C
 */
void Actor_UpdateAnimation(u32 actorId)
{
    u8 byteActorId = actorId;
    struct ActorState *actor = &gActorStates[byteActorId];

    if (!(actor->flags & CORE_ACTOR_FLAG_CUSTOM_ANIMATION))
        Actor_UpdateStandardAnimationInline(actor);
    else
        Actor_UpdateCustomAnimation(byteActorId);
}

/**
 * @brief 推进角色自定义动画时间线，切换精灵帧并提交所需资源
 *
 * @note 动画槽为 0xFF 或计时已到 0xFF 时跳过；按循环标志重置或结束时间线。
 * @address 0x080029D8
 */
void Actor_UpdateCustomAnimation(u8 actorId)
{
    struct ActorState *actor = &gActorStates[actorId];
    const u8 *data;
    const u8 *const *animations;
    const u8 *keyframes;
    u8 animationSlot;
    u16 timer;
    u16 value;
    u16 remaining;

    if (actor->customAnimationSlot == CORE_ACTOR_ANIMATION_DISABLED)
        return;
    animations = gActorAnimationDefinitions;
    animationSlot = actor->customAnimationSlot;
    data = animations[animationSlot];
    timer = actor->customAnimationTimer;
    if (timer == CORE_ACTOR_ANIMATION_COMPLETE)
        return;
    keyframes = data + (data[offsetof(struct ActorAnimationDefinition, timelineOffset)] + (data[offsetof(struct ActorAnimationDefinition, timelineOffset) + 1] << 8));
    if (timer == 0)
    {
        u16 transferSlot;

        if (data[offsetof(struct ActorAnimationDefinition, paletteBankCount)] + (data[offsetof(struct ActorAnimationDefinition, paletteBankCount) + 1] << 8) == 2)
        {
            transferSlot = Sprite_FindFreePaletteTransfer();
            Sprite_QueuePaletteTransfer(transferSlot,
                gActorAnimationPalettes[actor->customAnimationSlot],
                gActorAnimationRenderSlots[actor->customAnimationSlot] + OBJ_PALETTE_FIRST_BANK, 2);
        }
        else
        {
            transferSlot = Sprite_FindFreePaletteTransfer();
            Sprite_QueuePaletteTransfer(transferSlot,
                gActorAnimationPalettes[actor->customAnimationSlot],
                gActorAnimationRenderSlots[actor->customAnimationSlot] + OBJ_PALETTE_FIRST_BANK, 0);
        }
        keyframes += sizeof(struct ActorAnimationTimeline);
        {
            u32 offsetsAddress;

            value = Actor_GetAnimationFrameTableOffsetInline(keyframes);
            offsetsAddress = value + (u32)data;
            Actor_BuildAnimationFrame(actorId, Actor_ResolveAnimationFrameInline(data, offsetsAddress));
        }
        actor->customAnimationTimer++;
        return;
    }

    value = keyframes[offsetof(struct ActorAnimationTimeline, duration)] | (keyframes[offsetof(struct ActorAnimationTimeline, duration) + 1] << 8);
    remaining = keyframes[offsetof(struct ActorAnimationTimeline, recordCount)] | (keyframes[offsetof(struct ActorAnimationTimeline, recordCount) + 1] << 8);
    keyframes += sizeof(struct ActorAnimationTimeline);
    if (timer >= value)
    {
        if (!(gActorAnimationSlotFlags[animationSlot] & CORE_ACTOR_ANIMATION_LOOP))
        {
            actor->customAnimationTimer = CORE_ACTOR_ANIMATION_COMPLETE;
            return;
        }
        actor->customAnimationTimer = 0;
    }

    while (remaining != 0)
    {

        timer = actor->customAnimationTimer;
        if (timer == keyframes[offsetof(struct ActorAnimationKeyframe, endTick)] + (keyframes[offsetof(struct ActorAnimationKeyframe, endTick) + 1] << 8) || timer == 0)
        {
            u32 offsetsAddress;

            Sprite_FreeChain(&gSpriteNodes[actor->spriteSlot]);
            {
                u16 tableOffset;

                if (actor->customAnimationTimer == 0)
                    tableOffset = Actor_GetAnimationFrameTableOffsetInline(keyframes);
                else
                    tableOffset = Actor_GetAnimationFrameTableOffsetInline(keyframes + sizeof(struct ActorAnimationKeyframe));
                offsetsAddress = tableOffset + (u32)data;
            }
            Actor_BuildAnimationFrame(actorId, Actor_ResolveAnimationFrameInline(data, offsetsAddress));
            break;
        }
        keyframes += sizeof(struct ActorAnimationKeyframe);
        remaining--;
    }
    if (actor->customAnimationTimer != CORE_ACTOR_ANIMATION_COMPLETE)
        actor->customAnimationTimer++;
}

/**
 * @brief 解析六字节子精灵记录，排队图块传输并建立角色精灵链
 *
 * @note actorId 取低八位；空帧仍先分配链首节点。
 * @address 0x08002B54
 */
void Actor_BuildAnimationFrame(u32 actorId, const u8 *frame)
{
    struct ActorState *actor;
    struct SpriteNode *node;
    struct SpriteNode *nextNode;
    u16 priorityBits;
    u8 partOffset;
    u16 destTile;
    u8 remainingParts;
    const struct ActorAnimationFramePart *part;
    u8 tileCount;
    u16 transferSlot;
    const u8 *source;
    u8 *dest;
    u8 sourceTile;
    u16 attr0;
    u16 attr1;
    u16 attr2;
    s16 mirroredX;
    u8 actorIndex = (u8)actorId;

    actor = &gActorStates[actorIndex];
    if (actorIndex <= CORE_AUXILIARY_ACTOR_ID)
    {
        priorityBits = 0x800;
        if (gSceneState == 11)
            priorityBits = 0x400;
    }
    else
        priorityBits = 0;

    partOffset = frame[offsetof(struct ActorAnimationFrameHeader, prefixPartCount)]
        * sizeof(struct ActorAnimationFramePart) + sizeof(struct ActorAnimationFrameHeader);
    remainingParts = frame[offsetof(struct ActorAnimationFrameHeader, partCount)];
    actor->spriteSlot = Sprite_FindFreeNode();
    node = &gSpriteNodes[actor->spriteSlot];
    destTile = gActorAnimationRenderSlots[actor->customAnimationSlot] * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0;
    part = (const struct ActorAnimationFramePart *)(frame + partOffset);

    while (remainingParts != 0)
    {
        tileCount = gSpriteTileCounts[(part->attr0Hi >> 6) * CORE_SPRITE_SIZE_COUNT + (part->attr1Hi >> 6)];
        sourceTile = part->sourceTile;
        transferSlot = Sprite_FindFreeTileTransfer();
        source = gActorAnimationTileSources[actor->customAnimationSlot] + (sourceTile << 5);
        dest = (u8 *)OBJ_GRAPHICS + (destTile << 5);
        Sprite_QueueTileTransfer(transferSlot, source, dest, tileCount);

        attr0 = part->attr0Lo | (part->attr0Hi << 8);
        if ((gActorAnimationSlotFlags[actor->customAnimationSlot] & CORE_ACTOR_ANIMATION_FLIP_X) != 0)
            attr1 = (part->attr1Lo + (part->attr1Hi << 8)) | 0x1000;
        else
        {
            attr1 = part->attr1Lo | (part->attr1Hi << 8);
            node->xOffset = attr1 & 0x1FF;
        }
        node->yOffset = attr0 & 0xFF;
        attr2 = ((part->paletteOffsetBits << 8) & ~0xFFF) + (priorityBits + (gActorAnimationRenderSlots[actor->customAnimationSlot] << CORE_SPRITE_PALETTE_BANK_SHIFT) + destTile);
        nextNode = Sprite_InitNode(node, remainingParts, attr0, attr1, attr2);

        if ((gActorAnimationSlotFlags[actor->customAnimationSlot] & CORE_ACTOR_ANIMATION_FLIP_X) != 0)
        {
            gSpriteScratchWidth = gSpriteDimensions[((node->attr0 >> 11) & 0x18) + ((node->attr1 >> 13) & 6)];
            gSpriteScratchHeight = gSpriteDimensions[((node->attr0 >> 11) & 0x18) + ((node->attr1 >> 13) & 6) + offsetof(struct SpriteDimensions, height)];
            mirroredX = (~(attr1 & 0x1FF) - gSpriteScratchWidth) & 0x1FF;
            node->xOffset = mirroredX;
        }

        if (node->xOffset > 0xFF)
            node->xOffset--;
        node = nextNode;
        part++;
        destTile += tileCount;
        remainingParts--;
    }
}

/**
 * @brief 按方向键保持状态推进步行遇敌倒计时并报告触发
 *
 * @note 不检查实际位移；事件标志 0xBB 置位时停止递减，只重设过小计数。
 * @note 归零后间隔为 232 + 32 * (随机值 & 7)，场景 0x7B 的重设间隔减半；触发时返回 1。
 * @address 0x08002D54
 */
u8 Encounter_CheckWalking(void)
{
    if (gSceneEncounterConfigId != 0 && (gKeysHeld & 0xF0) != 0)
    {
        if (EventFlags_GetMask(0xBB) == 0)
        {
            gWalkingEncounterCountdown--;
            if (gWalkingEncounterCountdown == 0)
            {
                gWalkingEncounterCountdown = ((Random_NextByte() & 7) << 5) + 232;

                if (gSceneId == 0x7B)
                    gWalkingEncounterCountdown >>= 1;
                return 1;
            }
        }
        else if (gWalkingEncounterCountdown < 232)
        {
            gWalkingEncounterCountdown = 232;
            if (gSceneId == 0x7B)
                gWalkingEncounterCountdown = 116;
        }
    }
    return 0;
}

/**
 * @brief 推进LUNAR标识层的计时和混合演出
 *
 * @note 按 gTitleLogoStage 分派演出阶段：初始化混合窗口与系数、开启窗口、按帧推进
 *       混合系数或淡出，并在到点后进入下一阶段。阶段 0 直接返回。
 * @address 0x08002DDC
 */
void TitleLogo_Update(void)
{
    if (gTitleLogoStage == 0)
        return;

    switch (gTitleLogoStage)
    {
    case 1:
        (*(vu16 *)REG_DISPCNT) &= 0xFEFF;
        gBlendControl = 0x1E41;
        gBlendCoefficients = 0x0F00;
        gTitleLogoFrame = 0;
        return;

    case 2:
    case 3:
    case 4:
    case 10:
        break;

    case 5:
        (*(vu16 *)REG_DISPCNT) |= 0x0100;
        gBlendCoefficients = 0x0F00;
        gTitleLogoStage++;
        break;

    case 6:
        gTitleLogoFrame++;
        gBlendCoefficients &= 0x0F00;
        gBlendCoefficients |= (gTitleLogoFrame >> 2) & 0x1F;
        if ((gTitleLogoFrame >> 2) == 0x1F)
        {
            gTitleLogoStage++;
            gTitleLogoFrame = 0;
        }
        break;

    case 7:
        gTitleLogoFrame++;
        if (!(gTitleLogoFrame & 3))
        {
            gBlendCoefficients -= 0x100;
            if (!(gBlendCoefficients & 0xFF00))
            {
                gTitleLogoStage++;
                gTitleLogoFrame = gBlendCoefficients & 0xFF00;
            }
        }
        break;

    case 8:
        gTitleLogoFrame++;
        if (gTitleLogoFrame > 0x1B3)
        {
            gTitleLogoStage++;
            gTitleLogoFrame = 0;
        }
        break;

    case 9:
        gTitleLogoFrame++;
        gBlendCoefficients = (((gTitleLogoFrame >> 2) & 0x1F) << 8)
            | ((0x1F - (gTitleLogoFrame >> 2)) & 0x1F);
        if (gBlendCoefficients == 0x1F00)
        {
            gTitleLogoStage++;
            gTitleLogoFrame = 0;
        }
        break;
    }
}

/**
 * @brief 在VBlank中上传或清理LUNAR标识层资源
 *
 * @note 按 gTitleLogoStage 逐阶段上传资源：阶段 1 设置 BG0 控制、DMA 调色板并解压
 *       图块表，阶段 2/3/4 依次解压三块图形，阶段 5..9 无操作，阶段 10 关闭 OBJ
 *       窗口映射、恢复混合参数、用零填充调色板图块表并复位阶段。每完成一次
 *       上传阶段自增，全部结束后阶段归零。
 * @address 0x08002F6C
 */
void TitleLogo_UpdateVBlank(void)
{
    switch (gTitleLogoStage)
    {
    case 1:
        (*(vu16 *)REG_BG0CNT) = (31 << BG_SCREEN_BASE_SHIFT) | (2 << BG_CHAR_BASE_SHIFT);
        DmaCopy(3, gTitleLogoPalette, (void *)0x050001C0, 0x20, 16);
        LZ77UnCompVram((void *)gTitleLogoPalette + 0x20, BG_SCREEN_ADDR(31));
        gTitleLogoStage++;
        break;
    case 2:
        LZ77UnCompVram((void *)gTitleLogoGraphicsPart0, (void *)0x06008000);
        gTitleLogoStage++;
        break;
    case 3:
        LZ77UnCompVram((void *)gTitleLogoGraphicsPart1, (void *)0x06008800);
        gTitleLogoStage++;
        break;
    case 4:
        LZ77UnCompVram((void *)gTitleLogoGraphicsPart2, (void *)0x06009000);
        gTitleLogoStage++;
        break;
    case 10:
        (*(vu16 *)REG_DISPCNT) &= 0xFEFF;
        gBlendControl = 0x1C12;
        gBlendCoefficients = 0x0C07;
        {
            u16 fillValue;
            u16 *fillSource = &fillValue;
        
            *fillSource = (u16)(0);
            CpuSet(fillSource, BG_SCREEN_ADDR(31),
                DMA_16BIT_BUS | DMA_SRC_FIX | ((0x800) / 2 & 0x1FFFFF));
        }
        gTitleLogoStage = 0;
    default:
        return;
    }
}

/**
 * @brief 清空精灵绘制顺序并派发当前场景状态的处理函数
 *
 * @address 0x08003088
 */
void Scene_Update(void)
{
    Input_PollKeys();
    Sprite_ClearDrawOrder();
    gSceneStateHandlers[gSceneState]();
}

/**
 * @brief 等待屏幕过渡后派发完整地图入场
 *
 * @address 0x080030B0
 */
void Scene_UpdateMapTransition(void)
{
    if (gScreenTransitionType == 0 && gScenePhase == 1)
    {
        gSceneState = 2;
        gVBlankUpdateMode = 1;
    }
    else if (gScenePhase != 1)
    {
        gSceneTransitionCounter = (gSceneTransitionCounter + 1) & 1;
        gScenePhase = 1;
        Palette_SaveTransitionSource();
        Transition_Start(4);
    }
    Scene_UpdateFrame();
}

/**
 * @brief 转交菜单更新、绘制并汇总OAM
 *
 * @address 0x08003114
 */
void Scene_UpdateMenu(void)
{
    Menu_UpdateState();
    Menu_UpdateFrame();
    Sprite_BuildOamBuffer();
}

/**
 * @brief 更新世界地图输入、标记、玩家、OAM和调色板
 *
 * @address 0x08003128
 */
void Scene_UpdateWorldMap(void)
{
    if ((gScanlineBlendFlags & 0x80) == 0 && gScreenTransitionType == 0)
        WorldMap_UpdateInput(gKeysPressed);
    WorldMap_DrawMarkers();
    Player_UpdateActors();
    Sprite_BuildOamBuffer();
    Palette_Update();
}

/**
 * @brief 等待世界地图退出过渡，再派发地图入场
 *
 * @address 0x08003168
 */
void Scene_UpdateWorldMapExit(void)
{
    if (gScreenTransitionType == 0 && gScenePhase == 1)
    {
        Player_ResetFollowing();
        gSceneState = 2;
        gVBlankUpdateMode = 1;
    }
    else if (gScenePhase != 1)
    {
        gSceneTransitionCounter = (gSceneTransitionCounter + 1) & 1;
        gScenePhase = 1;
        Palette_SaveTransitionSource();
        Transition_Start(4);
        Sound_FadeOutBgm(46);
    }
    WorldMap_DrawMarkers();
    Player_UpdateActors();
    Sprite_BuildOamBuffer();
    Palette_Update();
}

/**
 * @brief 转交标题菜单、存档及收集流程，并更新调色板和OAM
 *
 * @address 0x080031E4
 */
void Scene_UpdateTitleMenu(void)
{
    TitleMenu_UpdateState();
    Palette_Update();
    Sprite_BuildOamBuffer();
}

/**
 * @brief 转交商店状态更新并汇总OAM
 *
 * @address 0x080031F8
 */
void Scene_UpdateShop(void)
{
    Shop_UpdateState();
    Sprite_BuildOamBuffer();
}

/**
 * @brief 清角色和精灵服务状态，禁用地图及装饰动画，生成空OAM
 *
 * @address 0x08003208
 */
void Scene_ClearForBackground(void)
{
    u16 entry;
    Actor_FreeAllSprites();
    Sprite_ClearDrawOrder();
    Sprite_ClearNodes();
    Sprite_ClearAffineMatrices();
    for (entry = 0; entry < CORE_SPRITE_OAM_COUNT; entry++)
    {
        gSpriteOamBuffer[entry].words[0] = 0;
        gSpriteOamBuffer[entry].words[1] = 0;
    }
    Sprite_ClearTileTransfers();
    Sprite_ClearPaletteTransfers();
    MapAnimation_DisableAll();
    FieldAnim_DisableAll();
    Sprite_BuildOamBuffer();
}

/**
 * @brief 为指定角色执行一次自定义动画更新
 *
 * @address 0x08003254
 */
void Actor_StepCustomAnimation(u8 actorId)
{
    Actor_UpdateCustomAnimation(actorId);
}

/**
 * @brief 执行已排队的精灵调色板传输并清除已完成请求
 *
 * @note 源字段基址在 DmaCopy 实参中形成，保留 DMA 寄存器地址先装载的顺序。
 * @address 0x08003264
 */
void Sprite_CopyPaletteTransfers(void)
{
    u16 index = 0;
    struct SpritePaletteTransferRequest *transfers = gSpritePaletteTransfers;

    for (; index < CORE_SPRITE_TRANSFER_COUNT; index++)
    {
        if (transfers[index].bankCount != 0)
        {
            u32 size = sizeof(PALETTE_RAM[0]);

            if (transfers[index].bankCount == 2)
                size *= 2;
            DmaCopy(3, Sprite_GetPaletteTransferSourceInline((const u8 *)&transfers[0].source, index),
                (u8 *)PALETTE_RAM + transfers[index].paletteSlot * sizeof(PALETTE_RAM[0]), (u32)(size), 16);
            transfers[index].bankCount = 0;
        }
    }
}

/**
 * @brief 按绘制顺序汇总精灵链到软件 OAM，并隐藏剩余条目
 *
 * @note 最多写入 128 条 OAM；剩余条目写入屏幕外坐标以隐藏。
 * @address 0x080032BC
 */
void Sprite_BuildOamBuffer(void)
{
    u16 entryCount = 0;
    u16 orderIndex = 0;

    for (; orderIndex < CORE_SPRITE_NODE_COUNT; orderIndex++)
    {
        struct SpriteNode *node = gSpriteDrawOrder[orderIndex];

        if (node != NULL)
        {
            u8 remaining = node->chainInfo & 0x7F;

            if (remaining != 0)
            {
                do
                {
                    remaining--;
                    if (remaining == 0xFF)
                        break;
                    node = Sprite_AppendOamNode(&entryCount, node);
                } while (node != NULL);
            }
            if (entryCount >= CORE_SPRITE_OAM_COUNT)
                return;
        }
    }

    if (entryCount >= CORE_SPRITE_OAM_COUNT)
        return;
    do
    {
        gSpriteOamBuffer[entryCount].words[0] = 0xA0;
        gSpriteOamBuffer[entryCount].words[1] = 0;
        entryCount++;
    } while (entryCount < CORE_SPRITE_OAM_COUNT);
}

/**
 * @brief 释放所有角色的主精灵链和阴影，并清空角色精灵槽
 *
 * @address 0x08003348
 */
void Actor_FreeAllSprites(void)
{
    s16 actorId = 0;

    for (; actorId < CORE_ACTOR_COUNT; actorId++)
    {
        u8 spriteSlot = gActorStates[actorId].spriteSlot;

        if (spriteSlot != 0)
        {
            Actor_ClearShadowInline(&gActorStates[actorId]);
            {
                u8 chainCount = gSpriteNodes[spriteSlot].chainInfo;
                struct SpriteNode *node;

                chainCount &= 0x7F;
                node = &gSpriteNodes[spriteSlot];

                while (chainCount != 0)
                {
                    struct SpriteNode *next;

                    node->chainInfo = 0;
                    next = node->next;
                    node->next = NULL;
                    node = next;
                    chainCount--;
                }
            }
        }
        gActorStates[actorId].spriteSlot = 0;
    }
}

/**
 * @brief 按场景角色配置列表初始化 NPC
 *
 * @note 从角色槽 2 起建立配置中的实例；特殊场景类型及空资源组直接跳过。
 * @address 0x080033E8
 */
void Actor_InitScene(u8 sceneId)
{
    s32 groupId;
    u16 groupOffset;
    u8 actorCount;
    const struct ActorSpawnConfig *config;
    u16 actorId;

    if (gSceneType & 0x80)
        return;
    groupId = gSceneResourceConfigs[sceneId].actorGroupId;
    actorId = groupId;
    if (actorId == 0)
        return;
    groupOffset = (actorId - 1) * sizeof(struct SceneActorResourceConfig);
    actorCount = ((const u8 *)gSceneActorResourceConfigs)[groupOffset];
    config = gSceneActorConfigs[groupId - 1];
    actorId = 2;
    for (; actorId < actorCount + 2; actorId++)
        Actor_Init((u8)actorId, config++);
}

/**
 * @brief 从出生配置初始化角色状态，并建立标准或自定义精灵节点
 *
 * @address 0x0800345C
 */
void Actor_Init(u8 actorId, const struct ActorSpawnConfig *config)
{
    struct ActorState *actor = &gActorStates[actorId];
    u8 spriteSlot = Sprite_FindFreeNode();
    struct SpriteNode *node;
    struct SpriteNode *next;
    u16 attr0, attr1, attr2;
    u8 direction;

    if (spriteSlot <= CORE_SPRITE_SEARCH_LAST)
    {
        node = &gSpriteNodes[spriteSlot];
        actor->spriteSlot = spriteSlot;
        actor->flags = config->flags;
        actor->graphicsSlot = config->graphicsSlot;
        actor->paletteSlot = config->paletteSlot;
        direction = config->direction;
        actor->direction = direction;
        actor->x = config->tileX * 8;
        actor->y = (config->tileY + 1) * 8;
        actor->minTileX = config->minTileX;
        actor->minTileY = config->minTileY;
        actor->maxTileX = config->maxTileX;
        actor->maxTileY = config->maxTileY;
        actor->moveSpeed = config->moveSpeed;
        actor->scriptEntryOrMenuState = config->scriptEntryId;
        actor->commandData = config->commandData;
        actor->animationCounter = 0;
        actor->movementDirection = direction;
        actor->moveTimer = 1;
        actor->waitTimer = 0;
        actor->stateFlags = 0;
        actor->commandOffset = 0;
        actor->verticalOffset = 0;
        actor->shadowSpriteSlot = 0;
        actor->verticalTimer = 0;
        actor->customAnimationTimer = 0;
        actor->customAnimationSlot = 0xFF;

        if (!(actor->flags & CORE_ACTOR_FLAG_CUSTOM_ANIMATION))
        {
            if (actor->flags & 4)
            {
                attr0 = 0;
                attr1 = 0x8000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0) & 0x3FF);
                node->xOffset = 0x1F8;
                node->yOffset = 0xE0;
                Sprite_InitNode(node, 1, attr0, attr1, attr2);
            }
            else if (actor->flags & 0x10)
            {
                attr0 = 0x4000;
                attr1 = 0xC000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0) & 0x3FF);
                node->xOffset = 0x1E8;
                node->yOffset = 0xF8;
                Sprite_InitNode(node, 1, attr0, attr1, attr2);
            }
            else if (actor->flags & 0x20)
            {
                attr0 = 0;
                attr1 = 0x8000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xB0) & 0x3FF);
                node->xOffset = 0x1F8;
                node->yOffset = 0xE8;
                next = Sprite_InitNode(node, 2, attr0, attr1, attr2);
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0) & 0x3FF);
                next->xOffset = 0x1F8;
                next->yOffset = 0xC8;
                Sprite_InitNode(next, 1, attr0, attr1, attr2);
            }
            else if (actor->flags & 0x40)
            {
                attr0 = 0;
                attr1 = 0x8000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0) & 0x3FF);
                node->xOffset = 0x1F8;
                node->yOffset = 0xEE;
                next = Sprite_InitNode(node, 3, attr0, attr1, attr2);
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xB0) & 0x3FF);
                next->xOffset = 0x18;
                next->yOffset = 0xEE;
                next = Sprite_InitNode(next, 2, attr0, attr1, attr2);
                attr0 = 0x8000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xC0) & 0x3FF);
                next->xOffset = 0x38;
                next->yOffset = 0xEE;
                Sprite_InitNode(next, 1, attr0, attr1, attr2);
            }
            else
            {
                attr0 = 0;
                attr1 = 0x4000;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA0) & 0x3FF);
                node->xOffset = 0;
                node->yOffset = 0xE8;
                next = Sprite_InitNode(node, 2, attr0, attr1, attr2);
                attr0 = 0x4000;
                attr1 = 0;
                attr2 = (actor->paletteSlot << 12) + 0x800
                    + ((actor->graphicsSlot * CORE_ACTOR_GRAPHICS_TILE_COUNT + 0xA4) & 0x3FF);
                next->xOffset = 0;
                next->yOffset = 0xF8;
                Sprite_InitNode(next, 1, attr0, attr1, attr2);
            }
        }
        else
        {
            node->chainInfo = 0x81;
            node->next = NULL;
        }
        node->flags = 0;
    }
}

