            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[12]);
        if (EventFlags_GetMask(0xE2))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[13]);
        if (EventFlags_GetMask(0xE3))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[14]);
        if (EventFlags_GetMask(0xE4))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[15]);
        if (EventFlags_GetMask(0xE5))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[16]);
        if (EventFlags_GetMask(0xE6))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[17]);
        if (EventFlags_GetMask(0xE7))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[18]);
        if (EventFlags_GetMask(0xE8))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[19]);
        if (EventFlags_GetMask(0xE9))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[20]);
        if (EventFlags_GetMask(0xEA))
            MapAnimation_ApplyCompletedChanges(slot, gMapAnimationGroups[21]);
