/**
 * @brief 从资源流初始化矩形地图动画，并返回下一条记录
 *
 * @note 图层编号从资源低位映射为 1 或 2；计时从零开始。
 * @address 0x08007964
 */
const u8 *MapAnimation_Init(u16 slot, const u8 *data)
{
    struct MapAnimationState *animation = &gMapAnimationStates[slot];

    animation->layer = (data[0] & 1) + 1;
    animation->flags = data[1];
    data += 2;
    animation->frameCount = data[0];
    data++;
    animation->frameShift = data[0];
    data++;
    animation->tileX = data[0];
    data++;
    animation->tileY = data[0];
    data++;
    animation->tileWidth = data[0];
    data++;
    animation->tileHeight = data[0];
    data++;
    animation->timer = 0;
    animation->frames = (const u16 *)data;
    return data + (animation->tileWidth * animation->tileHeight) * animation->frameCount * sizeof(u16);
}

/**
 * @brief 初始化矩形地图动画，并将计时定位到最后阶段
 *
 * @note 计时设为 (frameCount<<frameShift)-2，返回下一条资源记录。
 * @address 0x080079BC
 */
const u8 *MapAnimation_InitCompleted(u16 slot, const u8 *data)
{
    struct MapAnimationState *animation = &gMapAnimationStates[slot];

    animation->layer = (data[0] & 1) + 1;
    animation->flags = data[1];
    data += 2;
    animation->frameCount = data[0];
    data++;
    animation->frameShift = data[0];
    data++;
    animation->tileX = data[0];
    data++;
    animation->tileY = data[0];
    data++;
    animation->tileWidth = data[0];
    data++;
    animation->tileHeight = data[0];
    data++;
    animation->timer = (animation->frameCount << animation->frameShift) - 2;
    animation->frames = (const u16 *)data;
    return data + (animation->tileWidth * animation->tileHeight) * animation->frameCount * sizeof(u16);
}

/**
 * @brief 推进单个矩形动画并写入其指定的展开地图层
 *
 * @note 暂停或停用时跳过；单次动画结束后停用，循环动画回到第 0 帧。
 * @address 0x08007A1C
 */
void MapAnimation_UpdateSlot(s16 slot)
{
    u16 frame;
    u16 *destination;
    const u16 *source;
    u8 rows;
    u8 columns;

    if (gMapAnimationStates[slot].layer != 0
        && (u8)(gMapAnimationStates[slot].flags & 2) == 0)
    {
        gMapAnimationStates[slot].timer++;
        frame = gMapAnimationStates[slot].timer >> gMapAnimationStates[slot].frameShift;
        if (frame >= gMapAnimationStates[slot].frameCount)
        {
            if (gMapAnimationStates[slot].flags & 1)
                gMapAnimationStates[slot].layer = 0;
            gMapAnimationStates[slot].timer = 0;
            frame = 0;
        }
        if (gMapAnimationStates[slot].layer != 0)
        {
            s32 layerOffset = (gMapAnimationStates[slot].layer - 1) << 15;
            u16 *row = MAP_EXPANDED_A[gMapAnimationStates[slot].tileY];
            layerOffset += (u32)row;
            destination = (u16 *)layerOffset + gMapAnimationStates[slot].tileX;
            source = gMapAnimationStates[slot].frames
                + gMapAnimationStates[slot].tileWidth * gMapAnimationStates[slot].tileHeight * frame;
            rows = gMapAnimationStates[slot].tileHeight;
            while (rows != 0)
            {
                columns = gMapAnimationStates[slot].tileWidth;
                while (columns != 0)
                {
                    *destination++ = *source++;
                    columns--;
                }
                destination += CORE_MAP_EXPANDED_WIDTH - gMapAnimationStates[slot].tileWidth;
                rows--;
            }
        }
    }
}

/**
 * @brief 用玩家接触的最多四个16像素格查询地图触发记录
 *
 * @address 0x08007ADC
 */
s32 Map_FindPlayerEvent(s16 x, s16 y)
{
    s32 sample;
    s32 tileY;
    const u8 *event;
    u8 remaining;

    for (sample = 1; (u32)sample < 4; sample = (u16)(sample + 1))
    {
        gMapEventSampleXs[sample] |= 0xFF;
        gMapEventSampleYs[sample] |= 0xFF;
    }
    sample = x >> 4;
    gMapEventSampleXs[0] = sample;
    tileY = y >> 4;
    gMapEventSampleYs[0] = tileY;
    if ((x & 15) != 0)
    {
        gMapEventSampleXs[1] = sample + 1;
        gMapEventSampleYs[1] = tileY;
        if ((y & 15) > 8)
        {
            gMapEventSampleXs[2] = sample;
            gMapEventSampleYs[2] = tileY + 1;
            gMapEventSampleXs[3] = sample + 1;
            gMapEventSampleYs[3] = tileY + 1;
        }
    }
    else if ((y & 15) > 8)
    {
        gMapEventSampleXs[2] = sample;
        gMapEventSampleYs[2] = tileY + 1;
    }
    event = (const u8 *)gMapEventConfig->triggers;
    remaining = *event++;
    while (remaining != 0)
    {
        for (sample = 0; (u32)sample < 4; sample = (u16)(sample + 1))
        {
            if (gMapEventSampleXs[sample] != 0xFF
                && gMapEventSampleXs[sample] == event[0]
                && gMapEventSampleYs[sample] == event[1])
            {
                gMapEventType = event[2];
                gMapEventIndex = event[3];
                return 1;
            }
        }
        event += sizeof(struct MapEventTrigger);
        remaining--;
    }
    return 0;
}

/**
 * @brief 按事件类别派发换图、同图定位、世界地图或脚本
 *
 * @address 0x08007BD0
 */
s32 Map_RunPlayerEvent(void)
{
    const u8 *config = (const u8 *)gMapEventConfig;
    u32 offset = gMapEventType * sizeof(void *) + offsetof(struct MapEventConfig, exits);
    const u8 *record = *(const u8 *const *)(config + offset);
    u8 entryId;

    switch (gMapEventType)
    {
    case 0:
        record += gMapEventIndex * sizeof(struct MapExitRecord);
        gPendingSceneId = *record++;
        gSceneEntryTileX = *record++;
        gSceneEntryTileY = *record++;
        gSceneEntryDirection = *record++;
        gSceneCameraRegionId = record[0] + (record[1] << 8);
        gSceneState = 3;
        SystemFlags_ClearLocal();
        return 1;
    case 1:
        record += gMapEventIndex * sizeof(struct MapRepositionRecord);
        gSceneEntryTileX = *record++;
        gSceneEntryTileY = *record++;
        gSceneEntryDirection = *record++;
        gSceneCameraRegionId = record[0] + (record[1] << 8);
        gSceneState = 4;
        return 1;
    case 2:
        record += gMapEventIndex * sizeof(struct WorldMapEntryRecord);
        gWorldMapRegionId = record[0];
        gWorldMapLocationId = record[1];
        gSceneState = 8;
        SystemFlags_ClearLocal();
        return 1;
    case 3:
        record += gMapEventIndex * sizeof(struct MapScriptEventRecord);
        entryId = record[0];
        if (SystemFlags_GetMask(record[1]) == 0)
        {
            Script_Start(entryId, 2);
            return 1;
        }
        return 0;
    case 4:
        record += gMapEventIndex * sizeof(struct MapDirectionalScriptEventRecord);
        entryId = *record++;
        if ((gKeysPressed & 1) != 0)
        {
            if (record[1] > 7 || record[1] == gPlayerDirection)
            {
                if (SystemFlags_GetMask(record[0]) == 0)
                    Script_Start(entryId, 2);
            }
        }
        return 0;
    }
    return 1;
}

/**
 * @brief 加载世界地图图形、文字与区域资源
 *
 * @address 0x08007D5C
 */
void WorldMap_LoadResources(u8 regionId)
{

    u16 *tilemap;
    u16 entry;

    gVBlankUpdateMode = 3;
    HuffUnComp((void *)(gWorldMapCompressedGraphics[regionId]), ANIMATION_GRAPHICS_WORKSPACE);
    LZ77UnCompVram((void *)(ANIMATION_GRAPHICS_WORKSPACE), ((void *)VRAM));
    LZ77UnCompVram((void *)(gWorldMapCompressedLayouts[regionId]), BG_SCREEN_ADDR(28));

    DmaCopy(3, gWorldMapPalettes[regionId], PALETTE_RAM, 256, 16);
    LZ77UnCompVram((void *)(gSceneSharedTilePage0), BG_SCREEN_ADDR(16));
    func_08000F90();
    LZ77UnCompVram((void *)(gSceneSharedTilePage1), BG_SCREEN_ADDR(18));
    func_08000F90();
    LZ77UnCompVram((void *)(gSceneSharedTilePage2), BG_SCREEN_ADDR(20));
    func_08000F90();
    LZ77UnCompVram((void *)(gSceneSharedTilePage3), BG_SCREEN_ADDR(22));
    func_08000F90();
    DmaCopy(3, gSceneSharedPalettes, PALETTE_RAM[11], sizeof(gSceneSharedPalettes), 16);
    func_08000F90();
    LZ77UnCompVram((void *)(gWorldMapUiTilemap0), BG_SCREEN_ADDR(26));
    LZ77UnCompVram((void *)(gWorldMapUiTilemap1), (u8 *)BG_SCREEN_ADDR(26) + 0x400);
    LZ77UnCompVram((void *)(gWorldMapUiTilemap2), BG_SCREEN_ADDR(27));
    LZ77UnCompVram((void *)(gWorldMapUiTilemap3), (u8 *)BG_SCREEN_ADDR(27) + 0x400);
    DmaCopy(3, &gDefaultBackdropColor, PALETTE_RAM, sizeof(gDefaultBackdropColor), 16);
    (*(vu16 *)REG_DISPCNT) = ((*(vu16 *)REG_DISPCNT) & 0xE000) | 0x1560;
    *(vu16 *)REG_BG2CNT = 0x3C02;
    *(vu16 *)REG_BG3CNT = 0x3D01;
    (*(vu16 *)REG_BG0CNT) = 0x3F08;
    gBlendControl = 0x1E41;
    gBlendCoefficients = 0x1F00;
    DmaCopy(3, gSceneOverlayTiles0, BG_SCREEN_ADDR(24), sizeof(gSceneOverlayTiles0), 16);
    DmaCopy(3, gSceneOverlayPalette0, PALETTE_RAM[10], sizeof(gSceneOverlayPalette0), 16);
    Scene_FillEffectTilemap(0);
    DmaCopy(3, SCENE_EFFECT_TILEMAP, BG_SCREEN_ADDR(30), (u32)(BG_SCREEN_BLOCK_SIZE), 16);
    tilemap = (u16 *)gScriptTextTilemap;
    for (entry = 0; entry < 2048; entry++)
        *tilemap++ = 0;
    Menu_DrawLayout(gWorldMapRegionNameGroups[gWorldMapRegionId]);
    gBg1RasterMode = 1;
    *(vu16 *)REG_BG1CNT = 0x1E0F;
    (*(vu16 *)REG_DISPCNT) |= 0x200;
    Display_BuildBg1RasterOffsets(1);
    WorldMap_CreateMarkerSprites(regionId);
    gWorldMapLocationNameGroupId = gWorldMapLocationId;
}

/**
 * @brief 建立世界地图标记精灵并初始化脉动状态
 *
 * @note 单标记调色板的 -0x60 偏移在 DmaCopy 实参中更新，位于宏的 DMA 寄存器绑定之后。
 * @address 0x08007FB8
 */
void WorldMap_CreateMarkerSprites(u8 regionId)
{
    const u8 *graphics;
    struct SpriteNode *node;
    u8 slot;
    u8 paired;
    u16 attr0;
    u16 attr1;
    u16 attr2;

    if (regionId == 1)
    {
        paired = EventFlags_GetMask(255);
        if (paired != 0)
        {
            graphics = gWorldMapPairedMarkerTiles;
            LZ77UnCompVram((void *)(graphics), WORLD_MAP_MARKER_GRAPHICS);
            LZ77UnCompVram((void *)(graphics + 0x144), WORLD_MAP_SECOND_MARKER_GRAPHICS);
            DmaCopy(3, graphics - 0x180, OBJ_PALETTES[2], sizeof(OBJ_PALETTES[0]), 16);
            DmaCopy(3, graphics - 0x160, OBJ_PALETTES[3], sizeof(OBJ_PALETTES[0]), 16);
            slot = Sprite_FindFreeNode();
            node = &gSpriteNodes[slot];
            gWorldMapMarkerSpriteSlots[0] = slot;
            attr0 = 0;
            attr1 = 0x8000;
            attr2 = 0x2A00;
            node->xOffset = 0;
            node->yOffset = 0;
            Sprite_InitNode(node, 1, attr0, attr1, attr2);
            slot = Sprite_FindFreeNode();
            node = &gSpriteNodes[slot];
            gWorldMapMarkerSpriteSlots[1] = slot;
            attr2 = 0x3A10;
            node->xOffset = 0;
            node->yOffset = 0;
            Sprite_InitNode(node, 1, attr0, attr1, attr2);
        }
        else
        {
            graphics = gWorldMapSingleMarkerTiles;
            LZ77UnCompVram((void *)(graphics), WORLD_MAP_MARKER_GRAPHICS);
            DmaCopy(3, graphics -= 0x60, OBJ_PALETTES[2], sizeof(OBJ_PALETTES[0]), 16);
            slot = Sprite_FindFreeNode();
            node = &gSpriteNodes[slot];
            gWorldMapMarkerSpriteSlots[0] = slot;
            attr0 = 0;
            attr1 = 0x8000;
            attr2 = 0x2A00;
            node->xOffset = 0;
            node->yOffset = 32;
            Sprite_InitNode(node, 1, attr0, attr1, attr2);
            gWorldMapMarkerPulseDirection = 0;
            gWorldMapMarkerPulseFrame = 0;
        }
    }
    else
    {
        gWorldMapMarkerSpriteSlots[0] = 0;
        gWorldMapMarkerSpriteSlots[1] = 0;
    }
}

/**
 * @brief 选择区域和当前地点的FF终止连接列表，清选择并计数
 *
 * @note 保存当前连接列表的起始指针，清零选择索引，并统计到 0xFF 结束符前的项目数。
 * @address 0x08008124
 */
u32 WorldMap_LoadConnections(void)
{
    const u8 *list = gWorldMapConnectionLists;
    u8 i;
    u8 count;

    for (i = 0; i != gWorldMapRegionId; i++)
    {
        if (*list != 0xFF)
        {
            do
            {
                list++;
                if (*list != 0xFF)
                    continue;
                list++;
            } while (*list != 0xFF);
        }
        list++;
    }

    for (i = 0; i != gWorldMapLocationId; i++)
    {
        if (*list != 0xFF)
        {
            do
            {
                list++;
            } while (*list != 0xFF);
        }
        list++;
    }

    gWorldMapConnectionIds = list;
    gWorldMapConnectionIndex = 0;

    count = 0;
    while (*list != 0xFF)
    {
        list++;
        count++;
    }
    gWorldMapConnectionCount = count;
}

/**
 * @brief 绘制固定标记或按脉动计数绘制单个标记
 *
 * @address 0x080081C0
 */
void WorldMap_DrawMarkers(void)
{
    if (gWorldMapMarkerSpriteSlots[1] != 0)
    {
        Sprite_QueueChain(176, 24, gWorldMapMarkerSpriteSlots[1], 0, 1);
        Sprite_QueueChain(208, 48, gWorldMapMarkerSpriteSlots[0], 0, 1);
    }
    else if (gWorldMapMarkerSpriteSlots[0] != 0)
    {
        if (gWorldMapMarkerPulseDirection == 0)
        {
            gWorldMapMarkerPulseFrame++;
            if (gWorldMapMarkerPulseFrame == 192)
                gWorldMapMarkerPulseDirection = 1;
        }
        else
        {
            gWorldMapMarkerPulseFrame--;
            if (gWorldMapMarkerPulseFrame == 0)
                gWorldMapMarkerPulseDirection = 0;
        }
        Sprite_QueueChain(104, 48, gWorldMapMarkerSpriteSlots[0],
            (gWorldMapMarkerPulseFrame >> 6) + 16, 1);
    }
}

/**
 * @brief 处理世界地图方向选择、路线、目标确认和地点名称
 *
 * @note Actor 0 执行路线时不接受输入；方向切换优先于 A 键确认。
 * @address 0x08008254
 */
void WorldMap_UpdateInput(u16 keys)
{
    const u8 *connections;
    /* Reused as a zero loop guard, region index, then packed route endpoints. */
    u8 regionOrRoute;
    u8 location;
    u8 index;
    u16 offset;
    u16 *tilemap;

    if (gActorStates[0].stateFlags & CORE_ACTOR_STATE_COMMANDS_ACTIVE)
        return;

    gBlendCoefficients = 0xC0F;
    connections = gWorldMapConnectionIds;
    regionOrRoute = 0;
    location = 0xFF;
    index = gWorldMapConnectionIndex;
    /* Right/up advance; left/down go back, wrapping over locked connections. */
    if (keys & 0x50)
    {
        while (regionOrRoute == 0)
        {
            index++;
            if (index >= gWorldMapConnectionCount)
                index = 0;
            location = connections[index];
            if ((location & 0xF) <= 8)
                break;
            else if (EventFlags_GetMask(gWorldMapConnectionUnlockFlags[(location & 0xF) - 9]))
            {
                location = (location >> 4) & 0xF;
                break;
            }
        }
    }
    else if (keys & 0xA0)
    {
        while (regionOrRoute == 0)
        {
            index--;
            if (index == 0xFF)
                index = gWorldMapConnectionCount - 1;
            location = connections[index];
            if ((location & 0xF) > 8)
            {
                if (EventFlags_GetMask(gWorldMapConnectionUnlockFlags[(location & 0xF) - 9]))
                {
                    location = (location >> 4) & 0xF;
                    break;
                }
            }
            else
                break;
        }
    }

    if (index != gWorldMapConnectionIndex)
    {
        const u8 *records;
        u8 regionId;
        u8 bytes;

        Sound_PlaySfx(0, 0, 0);
        gWorldMapConnectionIndex = index;
        gWorldMapLocationNameGroupId = location & 0xF;
        location &= 0xF;
        records = gWorldMapLocationRecords;
        regionId = 0;
        bytes = *records * sizeof(struct WorldMapLocationRecord);
        records++;
        while (regionId != gWorldMapRegionId)
        {
            records += bytes;
            regionId++;
            bytes = *records * sizeof(struct WorldMapLocationRecord);
            records++;
        }
        records += location * sizeof(struct WorldMapLocationRecord);
        gWorldMapTargetX = records[0];
        gWorldMapTargetY = records[1];
        gActorStates[1].x = gWorldMapTargetX;
        gActorStates[1].y = gWorldMapTargetY - 8;
    }
    else if (keys & 1)
    {
        if (gWorldMapLocationId == (gWorldMapLocationNameGroupId & 0xF))
        {
            if (gWorldMapRegionId == 4 && gWorldMapLocationId == 0)
                return;
            offset = 0;
            for (; regionOrRoute != gWorldMapRegionId; regionOrRoute++)
            {
                if (gWorldMapRouteCommands[offset] != 0xFF)
                {
                    do
                    {
                        offset += 8;
                    } while (gWorldMapRouteCommands[offset] != 0xFF);
                }
                offset++;
            }
            offset += gWorldMapLocationId * 8;
            gPendingSceneId = gWorldMapRouteCommands[offset++];
            gSceneEntryTileX = gWorldMapRouteCommands[offset++];
            gSceneEntryTileY = gWorldMapRouteCommands[offset++];
            gSceneEntryDirection = gWorldMapRouteCommands[offset++];
            gSceneCameraRegionId = gWorldMapRouteCommands[offset]
                + (gWorldMapRouteCommands[offset + 1] << 8);
            Sound_PlaySfx(1, 0, 0);
            gBlendCoefficients = 0x1F00;
            gSceneState = 10;
        }
        else
        {
            regionOrRoute = ((gWorldMapLocationId & 0xF) << 4)
                | (gWorldMapLocationNameGroupId & 0xF);
            index = 0;
            do
            {
                if (gWorldMapRegionId == gWorldMapDestinationRecords[index++]
                    && regionOrRoute == gWorldMapDestinationRecords[index])
                {
                    index >>= 1;
                    break;
                }
                index++;
            } while (1);
            Sound_PlaySfx(1, 0, 0);
            Actor_SetCommandData(0, gWorldMapRouteCommandStreams[index]);
            Actor_StartCommands(0);
            gWorldMapLocationId = gWorldMapLocationNameGroupId;
            WorldMap_LoadConnections();
            gWorldMapConnectionIndex = 0;
        }
    }

    tilemap = WORLD_MAP_LOCATION_NAME_TILEMAP + 1;
    for (offset = 0; offset < 16; offset++)
        *tilemap++ = 0;
    tilemap = WORLD_MAP_LOCATION_NAME_TILEMAP + SCRIPT_TILEMAP_WIDTH + 1;
    for (offset = 0; offset < 16; offset++)
        *tilemap++ = 0;
    regionOrRoute = 0;
    offset = 0;
    while (regionOrRoute != gWorldMapRegionId)
    {
        if (gWorldMapRouteCommands[offset] != 0xFF)
        {
            do
            {
                offset += 8;
            } while (gWorldMapRouteCommands[offset] != 0xFF);
        }
        offset++;
        regionOrRoute++;
    }
    offset += gWorldMapLocationNameGroupId * 8;
    Menu_DrawSceneName(WORLD_MAP_LOCATION_NAME_TILEMAP, gWorldMapRouteCommands[offset], 11);
}

/**
 * @brief 准备一个8乘8图块图像的图块表、压缩图形和调色板上传
 *
 * @address 0x08008620
 */
void Scene_QueueOverlayImage(u8 imageId, u8 slot)
{
    u16 *tilemap;
    s32 tile;
    u16 column;
    u16 row;
    s32 attributes;

    if (imageId != 0)
    {
        if (imageId > 88)
            imageId = 0;
        imageId--;
        gPendingOverlaySlot = slot + 1;
        gPendingOverlayGraphics = gOverlayImageGraphics[imageId];
        gPendingOverlayPalette = gOverlayImagePalettes[gOverlayImagePaletteIds[imageId]];
        attributes = (slot & 2) ? 0xF2C0 : 0xE280;
        tilemap = gOverlayImageTilemapDestinations[slot];
        tile = 0;
        for (row = 0; row < 8; row++)
        {
            for (column = 0; column < 8; column++)
            {
                *tilemap++ = attributes + tile;
                tile = (u16)(tile + 1);
            }
            tilemap += 24;
        }
    }
    else
    {
        tilemap = gOverlayImageTilemapDestinations[slot];
        for (row = 0; row < 8; row++)
        {
            for (column = 0; column < 8; column++)
                *tilemap++ = 0;
            tilemap += 24;
        }
        gPendingOverlaySlot = 0;
    }
}

/**
 * @brief 更新随机背景偏移和闪烁混合效果
 *
 * @note 按 gSceneEffects.flags 的低三位分别更新滚动步长、闪烁混合系数与显示控制。
 * @address 0x080086FC
 */
void Scene_UpdateScreenEffects(void)
{
    if (gSceneEffects.flags & 1)
        gSceneEffects.scrollXStep = Random_NextByte() & gSceneEffects.backgroundMask;

    if (gSceneEffects.flags & 2)
        gSceneEffects.scrollYStep = Random_NextByte() & gSceneEffects.backgroundMask;

    if (gSceneEffects.flags & 4)
    {
        gSceneEffects.unknown06++;
        if (gSceneEffects.unknown06 > 0xF)
            gSceneEffects.unknown06 = 0;
        gBlendControl = 0x1C42;
        gBlendCoefficients = gSceneEffects.unknown06 | 0xF00;
        (*(vu16 *)REG_DISPCNT) |= 0x200;
    }
}

/**
 * @brief 使用专用分段VBlank协议装载脚本背景，设置FD场景格式
 *
 * @note 设置 0xFD 场景类型，通过分段 VBlank 上传请求装载背景。
 * @address 0x08008788
 */
void Scene_LoadScriptBackground(u8 backgroundId)
{

    const void *graphics;

    gScriptBackgroundUploadKind = 0;
    gScriptBackgroundPart = 0;
    gVBlankUpdateMode = VBLANK_UPDATE_SCRIPT_BACKGROUND;
    gSceneType = CORE_SCENE_TYPE_SCRIPT_BACKGROUND;
    Scene_ClearForBackground();
    VBlankIntrWait();
    Sound_Update();

    LZ77UnCompWram((void *)(gScriptBackgroundGraphics[backgroundId * 2]), ANIMATION_GRAPHICS_WORKSPACE);
    gScriptBackgroundPart = 0;
    gScriptBackgroundUploadKind = 1;
    VBlankIntrWait();
    Sound_Update();

    graphics = gScriptBackgroundGraphics[backgroundId * 2 + 1];
    if (graphics != NULL)
    {
        LZ77UnCompWram((void *)(graphics), ANIMATION_GRAPHICS_WORKSPACE);
        gScriptBackgroundPart = 1;
        gScriptBackgroundUploadKind = 1;
        VBlankIntrWait();
        Sound_Update();
    }

    DmaCopy(3, gScriptBackgroundPalettes[backgroundId], PALETTE_RAM, sizeof(gScriptBackgroundPalettes[backgroundId]), 32);
    DmaCopy(3, &gDefaultBackdropColor, PALETTE_RAM, sizeof(gDefaultBackdropColor), 16);
    System_WaitVBlankAndUpdateSound();

    LZ77UnCompWram((void *)(gScriptBackgroundTilemaps[backgroundId]), ANIMATION_GRAPHICS_WORKSPACE);
    gScriptBackgroundPart = 0;
    gScriptBackgroundUploadKind = 2;
    VBlankIntrWait();
    Sound_Update();
    System_WaitVBlankAndUpdateSound();

    (*(vu16 *)REG_DISPCNT) = 0x1960;
    *(vu16 *)REG_BG1CNT = 0;
    *(vu16 *)REG_BG2CNT = 0;
    *(vu16 *)REG_BG3CNT = 0x3C03;
}

/**
 * @brief 保存扫描线混合标志、步长及保留参数，初始化位置
 *
 * @note 保留参数的进一步用途尚未确认；按原例程保存并初始化扫描线位置。
 * @address 0x080088B4
 */
void Blend_StartScanlineEffect(u16 flags, s16 step, u16 unknownParameter)
{
    gScanlineBlendUnknownParameter = unknownParameter;
    gScanlineBlendStep = step;
    if (step < 0)
        gScanlineBlendPosition = 432;
    else
        gScanlineBlendPosition = 0;
    gScanlineBlendFlags = flags;
}

/**
 * @brief 为两层场景地图设置数据视图并依次展开布局
 *
 * @address 0x080088F4
 */
void Map_ExpandScene(void)
{
    if (gSceneType <= 0xFC)
    {
        gMapExpansionOutput = (u16 *)MAP_EXPANDED_A;
        gMapBlockDefinitions = MAP_BLOCK_DEFINITIONS_A;
        gMapChunkDefinitions = MAP_CHUNK_DEFINITIONS_A;
        gMapChunkGrid = MAP_CHUNK_GRID_A;
        Map_ExpandLayer();
        gMapExpansionOutput = (u16 *)MAP_EXPANDED_B;
        gMapBlockDefinitions = MAP_BLOCK_DEFINITIONS_B;
        gMapChunkDefinitions = MAP_CHUNK_DEFINITIONS_B;
        gMapChunkGrid = MAP_CHUNK_GRID_B;
        Map_ExpandLayer();
    }
}

/**
 * @brief 根据VCOUNT镜像选取窗口表行并配置DMA0
 *
 * @address 0x08008978
 */
void Transition_UpdateHBlank(void)
{
    u32 row;

    if ((u8)(gScreenTransitionType - 1) <= 1)
    {
        row = *(u8 *)REG_VCOUNT;
        if (row > 159)
        {
            if (row <= 225)
                return;
            row = 0;
        }
        else
            row = (u16)(row + 1);

        if (row > 81)
            row = (u16)(row - 82);
        else
            row = (u16)(81 - row);
        DmaSet(0, &gTransitionWindowRows[row], (void *)REG_WIN0H, 0xE0400001);
    }
}

/**
 * @brief 启动窗口或调色板过渡，保存过渡类型
 *
 * @address 0x080089E0
 */
void Transition_Start(u16 effect)
{
    switch (effect)
    {
    case 1:
        gTransitionWindowRadius = 0;
        *(vu16 *)REG_WIN0H = 240;
        *(vu16 *)REG_WIN0V = 160;
        *(vu16 *)REG_WININ = 0x3F;
        *(vu16 *)REG_WINOUT = 0;
        break;
    case 0:
        gTransitionWindowRadius = 240;
        break;
    default:
        Palette_StartTransition(effect - 3);
        break;
    }
    gScreenTransitionType = effect;
}

/**
 * @brief 清除所有矩形地图动画槽的图层编号以停用动画
 *
 * @address 0x08008A3C
 */
void MapAnimation_DisableAll(void)
{
    s16 index = 0;

    for (; index < CORE_MAP_ANIMATION_COUNT; index++)
        gMapAnimationStates[index].layer = 0;
}

/**
 * @brief 逐槽更新全部矩形地图动画
 *
 * @address 0x08008A60
 */
void MapAnimation_Update(void)
{
    s16 index = 0;

    for (; index < CORE_MAP_ANIMATION_COUNT; index++)
        MapAnimation_UpdateSlot(index);
}

/**
 * @brief 装载场景和世界地图共用的文字及界面图块、调色板
 *
 * @note 当前保留空函数，以上为原 ROM 行为。
 * @address 0x08008A80
 */
void Scene_LoadSharedTiles(u8 skipUiTiles)
{
    if (skipUiTiles == 0)
    {
        LZ77UnCompVram((void *)0x0809C8B4, (void *)0x0600C800);
        func_08000F90();
    }

    LZ77UnCompVram((void *)0x0809CB90, (void *)0x06008000);
    func_08000F90();

    LZ77UnCompVram((void *)0x0809D198, (void *)0x06009000);
    func_08000F90();

    LZ77UnCompVram((void *)0x0809D718, (void *)0x0600A000);
    func_08000F90();

    LZ77UnCompVram((void *)0x0809DCE8, (void *)0x0600B000);
    func_08000F90();

    DmaCopy(3, 0x0809C834, 0x05000160, 0x60, 16);
    func_08000F90();
}

/**
 * @brief 从相机区域配置设置左、上、右、下滚动边界
 *
 * @note 配置中的坐标和尺寸以 64 像素为单位。
 * @address 0x08008B14
 */
void Camera_SetBounds(u16 regionId)
{
    gCameraRegionLeft = gCameraRegionConfigs[regionId].x * CORE_CAMERA_REGION_PIXELS;
    gCameraRegionTop = gCameraRegionConfigs[regionId].y * CORE_CAMERA_REGION_PIXELS;
    gCameraRegionRight = gCameraRegionLeft + gCameraRegionConfigs[regionId].width * CORE_CAMERA_REGION_PIXELS;
    gCameraRegionBottom = gCameraRegionTop + gCameraRegionConfigs[regionId].height * CORE_CAMERA_REGION_PIXELS;
}

/**
 * @brief 载入世界地图主角和跟随者的标准图形与调色板
 *
 * @address 0x08008B5C
 */
void WorldMap_LoadPlayerResources(void)
{
    gActorGraphicsIds[0] = gPartyMembers[0];
    gActorPaletteIds[0] = gPartyMembers[0];
    Actor_LoadGraphics(0, gPartyMembers[0]);
    Actor_LoadPalette(0, gPartyMembers[0]);
    gActorGraphicsIds[1] = 11;
    gActorPaletteIds[1] = 11;
    Actor_LoadGraphics(1, 11);
    Actor_LoadPalette(1, 11);
}

/**
 * @brief 从指定槽开始装载一组矩形地图动画
 *
 * @address 0x08008BA4
 */
void MapAnimation_LoadGroup(u8 groupIndex, u8 firstSlot)
{
    const u8 *data = gMapAnimationGroups[groupIndex];
    u16 end = *(const u16 *)data + firstSlot;
    u16 slot;

    data += sizeof(u16);
    slot = firstSlot;
    for (; slot < end; slot++)
        data = MapAnimation_Init(slot, data);
}

/**
 * @brief 设置指定矩形地图动画的暂停位
 *
 * @note 暂停标志为 bit1；保留其他动画标志。
 * @address 0x08008BE4
 */
void MapAnimation_Pause(u8 slot)
{
    gMapAnimationStates[slot].flags |= 2;
}

/**
 * @brief 清除指定矩形地图动画的暂停位
 *
 * @note 仅清除 bit1，保留其他动画标志。
 * @address 0x08008BFC
 */
void MapAnimation_Resume(u8 slot)
{
    gMapAnimationStates[slot].flags &= 0xFD;
}

/**
 * @brief 返回指定矩形地图动画关联的地图层编号
 *
 * @note 0 表示停用，1 或 2 选择对应的展开地图层。
 * @address 0x08008C14
 */
u8 MapAnimation_GetLayer(u8 slot)
{
    return gMapAnimationStates[slot].layer;
}

/**
 * @brief 重载一个有效的标准图形、调色板槽
 *
 * @address 0x08008C24
 */
void Actor_ReloadResourceSlot(u8 slot)
{
    if ((gSceneType & CORE_SCENE_TYPE_FLAG_CUSTOM_ACTORS) == 0)
    {
        if (gActorGraphicsIds[slot] != 0xFF)
            Actor_LoadGraphics(slot, gActorGraphicsIds[slot]);
        if (gActorPaletteIds[slot] != 0xFF)
            Actor_LoadPalette(slot, gActorPaletteIds[slot]);
    }
}

/**
 * @brief 重新载入已登记的标准角色图形和调色板槽
 *
 * @note 跳过编号为 0xFF 的槽；特殊场景类型不加载标准角色资源。
 * @address 0x08008C70
 */
void Actor_ReloadResources(void)
{
    u8 slot = 0;

    for (; slot < CORE_ACTOR_RESOURCE_SLOT_COUNT; slot++)
    {
        if (!(gSceneType & 0x80))
        {
            if (gActorGraphicsIds[slot] != 0xFF)
                Actor_LoadGraphics(slot, gActorGraphicsIds[slot]);
            if (gActorPaletteIds[slot] != 0xFF)
                Actor_LoadPalette(slot, gActorPaletteIds[slot]);
        }
    }
}

/**
 * @brief 从当前区域的地点记录读取世界地图目标点的像素坐标
 *
 * @note 两个记录字节分别供世界地图入场及选点流程设置 X、Y 坐标。
 * @address 0x08008CC0
 */
void WorldMap_SelectLocation(u8 locationId)
{
    const u8 *records = gWorldMapLocationRecords;
    u8 regionId = 0;
    u8 bytes = *records * sizeof(struct WorldMapLocationRecord);
    records++;
    while (regionId != gWorldMapRegionId)
    {
        records += bytes;
        regionId++;
        bytes = *records * sizeof(struct WorldMapLocationRecord);
        records++;
    }
    records += locationId * sizeof(struct WorldMapLocationRecord);
    gWorldMapTargetX = records[0];
    gWorldMapTargetY = records[1];
}

/**
 * @brief 消费待上传图像，解压图形、复制调色板并清请求
 *
 * @address 0x08008D18
 */
void Scene_UploadOverlayImage(void)
{
    u16 *destination;

    if (gPendingOverlaySlot != 0)
    {
        LZ77UnCompVram((void *)(gPendingOverlayGraphics),
            (u8 *)BG_SCREEN_ADDR(26) + ((gPendingOverlaySlot - 1) >> 1) * 0x800);
        destination = PALETTE_RAM[14] + ((gPendingOverlaySlot - 1) >> 1) * 16;

        DmaCopy(3, gPendingOverlayPalette, destination,
            sizeof(PALETTE_RAM[0]), 16);
        gPendingOverlaySlot = 0;
    }
}

/**
 * @brief 按背景滚动模式计算角色绘制所需的竖直偏移
 *
 * @address 0x08008D78
 */
u16 Camera_GetBackgroundHeightOffset(void)
{
    switch (gBackgroundScrollMode)
    {
    case 2:
        return gBackgroundYState >> 4;
    case 4:
        return gBackgroundYState - 32;
    case 7:
        return gBackgroundYState - gCameraY;
    default:
        return 0;
    }
}

/**
 * @brief 保存供场景恢复使用的脚本bank编号
 *
 * @address 0x08008DCC
 */
void Scene_SetSavedScriptBank(u8 bankId)
{
    gSavedSceneScriptBankId = bankId;
}

/**
 * @brief 将默认背景色写入调色板的第零项
 *
 * @address 0x08008DD8
 */
void Palette_LoadDefaultBackdropColor(void)
{
    DmaCopy(3, &gDefaultBackdropColor, PALETTE_RAM, sizeof(gDefaultBackdropColor), 16);
}

/**
 * @brief 依次应用一组矩形地图变化的完成帧，并停用临时动画槽
 *
 * @note 多条变化复用同一动画槽，每条初始化到完成阶段、更新一次后清除图层编号。
 * @address 0x08008DF8
 */
void MapAnimation_ApplyCompletedChanges(u16 slot, const u8 *data)
{
    u16 count = *(const u16 *)data;

    data += sizeof(u16);
    if (count != 0)
    {
        struct MapAnimationState *animations = gMapAnimationStates;
        struct MapAnimationState *animation = animations + slot;

        for (; count != 0; count--)
        {
            data = MapAnimation_InitCompleted(slot, data);
            MapAnimation_UpdateSlot((s16)slot);
            animation->layer = 0;
        }
    }
}

/**
 * @brief 在共享效果图块表中写入一个8乘4图块区域，并请求上传
 *
 * @note frame 为零时从图块索引 0x20 开始，否则从零开始；填入 8×4 区域后请求上传。
 * @address 0x08008E44
 */
void Scene_DrawEffectTileBlock(u8 frame)
{
    u16 *destination = SCENE_EFFECT_TILE_BLOCK;
    u16 tileIndex = 0x20;
    u16 row;
    u16 column;

    if (frame != 0)
        tileIndex = 0;

    for (row = 0; row < 4; row++)
    {
        for (column = 0; column < 8; column++)
        {
            *destination++ = tileIndex + 0xA200;
            tileIndex++;
        }
        destination += 0x18;
    }
    gSceneEffects.tilemapUploadPending = 1;
}

/**
 * @brief 消费脚本背景的图形分段或图块表上传请求
 *
 * @note 当前保留空函数，以上为原 ROM 行为。
 * @address 0x08008E94
 */
void Scene_UploadScriptBackground(void)
{
    switch (gScriptBackgroundUploadKind)
    {
        case 1:
            switch (gScriptBackgroundPart)
            {
                case 0:
                    DmaCopy(3, (void *)0x02020000, (void *)0x06000000, 0xc00, 32);
                    break;

                case 1:
                    DmaCopy(3, (void *)0x02020000, (void *)0x06000C00, 0xc0, 32);
                    break;
            }
            gScriptBackgroundUploadKind = 0;
            break;

        case 2:
            DmaCopy(3, (void *)0x02020000, (void *)0x0600E000, 0x800, 32);
            gScriptBackgroundUploadKind = 0;
            break;
    }
}

/**
 * @brief 按当前场景配置和持久开启位初始化宝箱实例
 *
 * @address 0x08008F28
 */
void Chest_InitScene(u8 sceneId)
{
    u8 chestId = 0;
    u8 configId = 0;
    const struct ChestSpawnConfig *config = gChestConfigs;

    for (; chestId < CORE_CHEST_COUNT; configId++)
    {
        if (sceneId == config->sceneId)
        {
            struct ChestState *chests = gChestStates;
            struct ChestState *chest = &chests[chestId];

            chest->persistentId = configId;
            chest->x = config->tileX * 8;
            chest->y = config->tileY * 8 + 8;
            chest->scriptEntryId = config->scriptEntryId;
            chest->state = (gChestOpenBits[configId >> 3] >> (configId & 7)) & 1;
            if (config->paletteFlag != 0)
                chest->state |= CORE_CHEST_FLAG_ALT_PALETTE;
            Chest_BuildSprites(chestId);
            chestId++;
        }
        config++;
        if (configId == CORE_CHEST_CONFIG_COUNT - 1)
            break;
    }

    while (chestId < CORE_CHEST_COUNT)
    {
        gChestStates[chestId].state |= 0xFF;
        gChestStates[chestId].spriteSlot = 0;
        chestId++;
    }
}

/**
 * @brief 按宝箱开启状态和调色板标志建立精灵链
 *
 * @address 0x08008FD0
 */
void Chest_BuildSprites(u8 chestId)
{
    u8 spriteSlot = Sprite_FindFreeNode();
    struct ChestState *chests = gChestStates;
    struct ChestState *chest = &chests[chestId];
    struct SpriteNode *node;
    struct SpriteNode *next;
    u16 attr0, attr1, attr2;
    u16 palette;

    chest->spriteSlot = spriteSlot;
    node = &gSpriteNodes[spriteSlot];
    palette = (chest->state & CORE_CHEST_FLAG_ALT_PALETTE) ? 15 : 14;

    if ((chest->state & 0x7F) == 0)
    {
        attr0 = 0;
        attr1 = 0x4000;
        attr2 = (palette << 12) | 0x896;
        node->xOffset = 0;
        node->yOffset = 0xF0;
        Sprite_InitNode(node, 1, attr0, attr1, attr2);
    }
    else
    {
        attr0 = 0;
        attr1 = 0x4000;
        attr2 = (palette << 12) | 0x89C;
        node->xOffset = 0;
        node->yOffset = 0xF0;
        next = Sprite_InitNode(node, 2, attr0, attr1, attr2);
        attr0 = 0x4000;
        attr1 = 0;
        attr2 = (palette << 12) | 0x89A;
        next->xOffset = 0;
        next->yOffset = 0xE8;
        Sprite_InitNode(next, 1, attr0, attr1, attr2);
    }
    node->flags = 0;
}

/**
 * @brief 切换宝箱开启状态和持久位，播放音效并重建精灵链
 *
 * @note 实例编号与持久编号分别处理；完成后记录最后切换的宝箱实例。
 * @address 0x0800908C
 */
void Chest_Toggle(u8 chestId)
{
    struct ChestState *chest;
    struct ChestState *chests;
    u8 persistentId;

    if (gChestStates[chestId].state & CORE_CHEST_FLAG_OPEN)
        Sound_PlaySfx(9, 0, 0);
    else
        Sound_PlaySfx(8, 0, 0);

    chests = gChestStates;
    chest = &chests[chestId];
    chest->state ^= CORE_CHEST_FLAG_OPEN;
    persistentId = chest->persistentId;
    gChestOpenBits[persistentId >> 3] ^= 1 << (persistentId & 7);
    Sprite_FreeChain(&gSpriteNodes[chest->spriteSlot]);
    Chest_BuildSprites(chestId);
    gLastToggledChestId = chestId;
}

/**
 * @brief 载入宝箱共用的 OBJ 图形和调色板
 *
 * @address 0x08009114
 */
void Chest_LoadGraphics(void)
{
    if (!(gSceneType & 0x80))
    {
        func_08000F90();
        DmaCopy(3, gChestTiles, CHEST_GRAPHICS, sizeof(gChestTiles), 16);
        DmaCopy(3, gChestPalettes, CHEST_PALETTES, sizeof(gChestPalettes), 16);
    }
}

/**
 * @brief 清空宝箱持久开启位表
 *
 * @address 0x08009168
 */
void Chest_ClearOpenBits(void)
{
    u8 index = 0;

    do
    {
        gChestOpenBits[index++] = 0;
    } while (index < sizeof(gChestOpenBits));
}

/**
 * @brief 翻转指定持久宝箱编号的开启位
 *
 * @address 0x08009184
 */
void Chest_ToggleOpenBit(u8 persistentId)
{
    gChestOpenBits[persistentId >> 3] ^= 1 << (persistentId & 7);
}

/**
 * @brief 查询指定持久宝箱编号是否已开启
 *
 * @note 按持久编号查询位表，返回 0 或 1。
 * @address 0x080091A4
 */
u8 Chest_IsOpen(u8 persistentId)
{
    return (gChestOpenBits[persistentId >> 3] >> (persistentId & 7)) & 1;
}

/**
 * @brief 更新场景混合效果、调色板过渡或四轨调色板动画计时
 *
 * @address 0x080091C4
 */
void Palette_Update(void)
{
    u16 intensity;
    s16 slot;

    switch (gSceneBackgroundEffect)
    {
    case 8:
        gSceneBackgroundEffectFrame++;
        if (gSceneBackgroundEffectFrame > 111)
            gSceneBackgroundEffectFrame = 0;
        intensity = gSceneBackgroundEffectFrame >> 3;
        if (intensity > 7)
            intensity = 14 - intensity;
        intensity += 7;
        gBlendCoefficients = (gBlendCoefficients & 0xFFE0) | intensity;
        break;
    case 11:
        gSceneBackgroundEffectFrame++;
        if ((gSceneBackgroundEffectFrame & 6) == 0)
            gBlendCoefficients = 0xD03;
        else
            gBlendCoefficients = 0xF03;
        break;
    case 17:
        if (gSceneId == 107 && gSceneEffects.phase == 1)
        {
            gSceneBackgroundEffectFrame++;
            if (!(gSceneBackgroundEffectFrame & 16))
                gBlendCoefficients = (15 & ~((gSceneBackgroundEffectFrame >> 1) & 7)) | 0x1F08;
            else
                gBlendCoefficients = ((gSceneBackgroundEffectFrame >> 1) & 7) | 0x1F08;
        }
        break;
    }
    if (gPaletteTransitionType != 0)
        Palette_StepTransition();
    else
    {
        for (slot = 0; slot < CORE_PALETTE_ANIMATION_COUNT; slot++)
        {
            if (gPaletteAnimationFlags[slot] != 0
                && !(gPaletteAnimationFlags[slot] & CORE_PALETTE_ANIMATION_PAUSED))
            {
                gPaletteAnimationTimers[slot]++;
                if ((gPaletteAnimationTimers[slot] >> gPaletteAnimationFrameShifts[slot])
                    >= gPaletteAnimationFrameCounts[slot])
                {
                    if (gPaletteAnimationFlags[slot] & 2)
                        gPaletteAnimationFlags[slot] = 0;
                    else
                        gPaletteAnimationTimers[slot] = 0;
                }
            }
        }
    }
}

/**
 * @brief 上传调色板过渡，或消费精灵请求及四轨调色板动画
 *
 * @address 0x08009370
 */
void Palette_UpdateVBlank(void)
{
    s16 slot;


    if (gPaletteTransitionType != 0)
        Palette_UploadTransition();
    else
    {
        Sprite_CopyPaletteTransfers();
        slot = 0;

        for (; slot < CORE_PALETTE_ANIMATION_COUNT; slot++)
        {
            if (gPaletteAnimationFlags[slot] != 0
                && !(gPaletteAnimationFlags[slot] & CORE_PALETTE_ANIMATION_PAUSED))
            {
                s32 offset = gPaletteAnimationFrameIds[slot][gPaletteAnimationTimers[slot] >> gPaletteAnimationFrameShifts[slot]] * 32 + 2;
                DmaCopy(3, gPaletteAnimationColors + offset, gPaletteAnimationDestinations[slot], 32, 16);
            }
        }
    }
}

/**
 * @brief 初始化颜色过渡类型、分段状态和工作调色板
 *
 * @address 0x08009428
 */
void Palette_StartTransition(u8 transitionId)
{
    u16 color;
    u16 remaining;
    u16 *dest;

    gPaletteTransitionUploadPending = 0;
    gPaletteTransitionType = transitionId + 1;
    gPaletteTransitionFrame = 0;
    switch (gPaletteTransitionType)
    {
    case 1:
    case 7:
        color = 0x7FFF;
        *(vu16 *)REG_WIN0H = 0xF0FF;
        *(vu16 *)REG_WIN0V = 160;
        (*(vu16 *)REG_DISPCNT) |= 0x2000;
        *(vu16 *)REG_WININ = 0;
        *(vu16 *)REG_WINOUT = 0;
    case 3:
        if (gPaletteTransitionType == 3)
            color = 0;
        remaining = 512;
        dest = PALETTE_TRANSITION_COLORS;
        do
        {
            *dest++ = color;
            remaining--;
        } while (remaining != 0);
        DmaCopy(3, PALETTE_TRANSITION_COLORS, PALETTE_RAM, (u32)(PLTT_SIZE), 16);
        break;
    case 5:
        Palette_SaveTransitionSource();
    default:
        DmaCopy(3, PALETTE_TRANSITION_SOURCE, PALETTE_TRANSITION_COLORS, (u32)(PLTT_SIZE), 16);
        break;
    }
}

/**
 * @brief 上传一个四分之一调色板段，推进分段计数和完成状态
 *
 * @address 0x080094FC
 */
void Palette_UploadTransition(void)
{
    u16 *source;
    u16 quarter;

    if (gPaletteTransitionUploadPending != 0)
    {
        quarter = gPaletteTransitionFrame & 3;
        switch (quarter)
        {
        case 0: source = PALETTE_TRANSITION_COLORS; break;
        case 1: source = PALETTE_TRANSITION_COLORS + 128; break;
        case 2: source = PALETTE_TRANSITION_COLORS + 256; break;
        case 3: source = PALETTE_TRANSITION_COLORS + 384; break;
        }
        DmaCopy(3, source, (u8 *)PALETTE_RAM + (quarter << 8), 256, 16);
        gPaletteTransitionUploadPending = 0;
        gPaletteTransitionFrame++;
        if ((*(u16 *)&gPaletteTransitionType & 0xFF) > 6)
        {
            if (gPaletteTransitionFrame > 32)
            {
                if (gPaletteTransitionType == 7)
                {
                *(vu16 *)REG_WIN0H = 240;
                *(vu16 *)REG_WIN0V = 160;
                (*(vu16 *)REG_DISPCNT) |= 0x2000;
                *(vu16 *)REG_WININ = 0;
                *(vu16 *)REG_WINOUT = 0;
                }
                gPaletteTransitionType = 0;
                gScreenTransitionType = 0;
            }
        }
        else if (gPaletteTransitionFrame > 64)
        {
            if (gPaletteTransitionType == 2)
            {
                *(vu16 *)REG_WIN0H = 240;
                *(vu16 *)REG_WIN0V = 160;
                (*(vu16 *)REG_DISPCNT) |= 0x2000;
                *(vu16 *)REG_WININ = 0;
                *(vu16 *)REG_WINOUT = 0;
            }
            gPaletteTransitionType = 0;
            gScreenTransitionType = 0;
        }
        if (gPaletteTransitionFrame == 4)
        {
            *(vu16 *)REG_WIN0H = 240;
            *(vu16 *)REG_WIN0V = 256;
            *(vu16 *)REG_WININ = 63;
            *(vu16 *)REG_WINOUT = 63;
        }
    }
}

/**
 * @brief 根据过渡类型计算当前颜色分量并置上传请求
 *
 * @address 0x08009600
 */
void Palette_StepTransition(void)
{
    u8 amount;
    u8 reverseAmount;
    u8 type;
    u16 quarter;
    const u16 *source;
    u16 *dest;
    u16 remaining;
    u16 color;
    u8 red, green, blue;

    if (gPaletteTransitionUploadPending != 0)
        return;
    switch (gPaletteTransitionType)
    {
    case 1:
    case 3:
        amount = (64 - gPaletteTransitionFrame) >> 2;
        if (amount == 16)
            amount = 15;
        break;
    case 4:
        amount = gPaletteTransitionFrame >> 2;
        break;
    case 7:
        amount = ((32 - gPaletteTransitionFrame) >> 3) * 2;
        if (amount > 15)
            amount = 15;
        break;
    case 8:
        amount = gPaletteTransitionFrame >> 1;
        amount++;
        amount *= 2;
        if (amount > 15)
            amount = 15;
        break;
    default:
        amount = gPaletteTransitionFrame >> 2;
        amount++;
        break;
    }
    type = gPaletteTransitionType;
    if (type == 5 && gPaletteTransitionFrame > 32)
    {
        type = 6;
        reverseAmount = (64 - gPaletteTransitionFrame) >> 2;
    }
    quarter = gPaletteTransitionFrame & 3;
    switch (quarter)
    {
    case 0: source = PALETTE_TRANSITION_SOURCE; dest = PALETTE_TRANSITION_COLORS; break;
    case 1: source = PALETTE_TRANSITION_SOURCE + 128; dest = PALETTE_TRANSITION_COLORS + 128; break;
    case 2: source = PALETTE_TRANSITION_SOURCE + 256; dest = PALETTE_TRANSITION_COLORS + 256; break;
    case 3: source = PALETTE_TRANSITION_SOURCE + 384; dest = PALETTE_TRANSITION_COLORS + 384; break;
    }
    remaining = 128;
    switch (type)
    {
    case 3:
    case 4:
        while (remaining != 0)
        {
            if ((remaining & 15) != 0)
            {
                color = *source++;
                red = color & 31;
                green = (color >> 5) & 31;
                blue = (color >> 10) & 31;
                red = red - ((red * amount) >> 4);
                green = green - ((green * amount) >> 4);
                blue = blue - ((blue * amount) >> 4);
                if (red > 31) red = 31;
                if (green > 31) green = 31;
                if (blue > 31) blue = 31;
                *dest++ = red + (green << 5) + (blue << 10);
            }
            else
            {
                *dest++ = 0x7FFF;
                source++;
            }
            remaining--;
        }
        break;
    case 1:
    case 2:
        while (remaining != 0)
        {
            if ((remaining & 15) != 0)
            {
                color = *source++;
                red = color & 31;
                green = (color >> 5) & 31;
                blue = (color >> 10) & 31;
                red = red + (((31 - red) * amount) >> 4);
                green = green + (((31 - green) * amount) >> 4);
                blue = blue + (((31 - blue) * amount) >> 4);
                if (red > 31) red = 31;
                if (green > 31) green = 31;
                if (blue > 31) blue = 31;
                *dest++ = red + (green << 5) + (blue << 10);
            }
            else
            {
                *dest++ = 0x7FFF;
                source++;
            }
            remaining--;
        }
        break;
    case 5:
        while (remaining != 0)
        {
            if ((remaining & 15) != 0)
            {
                color = *source++;
                red = color & 31;
                green = (color >> 5) & 31;
                blue = (color >> 10) & 31;
                green = green + (((31 - green) * amount) >> 3);
                red = red + (((31 - red) * amount) >> 4);
                blue = blue + (((31 - blue) * amount) >> 4);
                if (red > 31) red = 31;
                if (green > 31) green = 31;
                if (blue > 31) blue = 31;
                *dest++ = red + (green << 5) + (blue << 10);
            }
            else
            {
                *dest++ = 0x7FFF;
                source++;
            }
            remaining--;
        }
        break;
    case 6:
        while (remaining != 0)
        {
            if ((remaining & 15) != 0)
            {
                color = *source++;
                red = color & 31;
                green = (color >> 5) & 31;
                blue = (color >> 10) & 31;
                green = green + (((31 - green) * reverseAmount) >> 3);
                red = red + (((31 - red) * reverseAmount) >> 4);
                blue = blue + (((31 - blue) * reverseAmount) >> 4);
                if (red > 31) red = 31;
                if (green > 31) green = 31;
                if (blue > 31) blue = 31;
                *dest++ = red + (green << 5) + (blue << 10);
            }
            else
            {
                *dest++ = 0x7FFF;
                source++;
            }
            remaining--;
        }
        break;
    case 7:
    case 8:
        while (remaining != 0)
        {
            if ((remaining & 15) != 0)
            {
                color = *source++;
                red = color & 31;
                green = (color >> 5) & 31;
                blue = (color >> 10) & 31;
                red = red + (((31 - red) * amount) >> 3);
                green = green + (((31 - green) * amount) >> 3);
                blue = blue + (((31 - blue) * amount) >> 3);
                if (red > 31) red = 31;
                if (green > 31) green = 31;
                if (blue > 31) blue = 31;
                *dest++ = red + (green << 5) + (blue << 10);
            }
            else
            {
                *dest++ = 0x7FFF;
                source++;
            }
            remaining--;
        }
        break;
    }
    gPaletteTransitionUploadPending = gPaletteTransitionType + 1;
}

/**
 * @brief 清四轨动画标志，保留其他状态
 *
 * @note 仅清四条调色板动画轨道的标志字节。
 * @address 0x08009A5C
 */
void Palette_DisableAnimations(void)
{
    s16 slot = 0;
    for (; slot < CORE_PALETTE_ANIMATION_COUNT; slot++)
        gPaletteAnimationFlags[slot] = 0;
}

/**
 * @brief 按一基组编号从轨道零开始绑定调色板动画
 *
 * @address 0x08009A7C
 * @note 组编号 0 不加载；有效组编号先减 1 再索引资源表。
 */
void Palette_LoadAnimationGroup(u8 groupId)
{
    const u8 *data;
    u8 remaining;
    s16 slot;
    if (groupId != 0)
    {
        data = gPaletteAnimationGroups[groupId - 1];
        remaining = *data++;
        slot = 0;
        while (remaining != 0)
        {
            data = Palette_InitAnimation(slot, data);
            remaining--;
            slot++;
        }
    }
}

/**
 * @brief 按零基组编号从指定轨道开始绑定调色板动画
 *
 * @note 组编号直接索引资源表，轨道起点由调用者指定。
 * @address 0x08009AC4
 */
void Palette_LoadAnimationGroupAt(u8 firstSlot, u8 groupIndex)
{
    const u8 *data = gPaletteAnimationGroups[groupIndex];
    u8 endSlot = firstSlot + *data++;
    u8 slot;
    for (slot = firstSlot; slot < endSlot; slot++)
        data = Palette_InitAnimation(slot, data);
}

/**
 * @brief 清除指定调色板动画的暂停位
 *
 * @note 仅清除标志中的 bit2（0x04）。
 * @address 0x08009B04
 */
void Palette_ResumeAnimation(u8 slot)
{
    gPaletteAnimationFlags[slot] &= ~CORE_PALETTE_ANIMATION_PAUSED;
}

/**
 * @brief 设置指定调色板动画的暂停位
 *
 * @note 仅设置标志中的 bit2（0x04）。
 * @address 0x08009B1C
 */
void Palette_PauseAnimation(u8 slot)
{
    gPaletteAnimationFlags[slot] |= CORE_PALETTE_ANIMATION_PAUSED;
}

/**
 * @brief 返回指定调色板轨道的完整标志字节
 *
 * @address 0x08009B34
 */
u8 Palette_GetAnimationFlags(u8 slot)
{
    return gPaletteAnimationFlags[slot];
}

/**
 * @brief 保存整个512色调色板到共享过渡源工作区
 *
 * @address 0x08009B44
 */
void Palette_SaveTransitionSource(void)
{
    DmaCopy(3, PALETTE_RAM, PALETTE_TRANSITION_SOURCE,
        (u32)(32 * sizeof(PALETTE_RAM[0])), 16);
}

/**
 * @brief 将整个512色调色板写为7FFF
 *
 * @address 0x08009B64
 */
void Palette_FillWhite(void)
{
    u16 remaining = 512;
    u16 *palette = &PALETTE_RAM[0][0];
    do
    {
        *palette++ = 0x7FFF;
        remaining--;
    } while (remaining != 0);
}

/**
 * @brief 解析调色板动画头，绑定目标颜色与帧编号流，并清零计时
 *
 * @note 目标从所选 bank 的颜色索引 1 开始；返回帧编号流之后的下一条记录。
 * @address 0x08009B84
 */
const u8 *Palette_InitAnimation(u8 slot, const u8 *data)
{
    gPaletteAnimationFlags[slot] = data[0];
    gPaletteAnimationFrameShifts[slot] = data[1];
    data += 2;
    gPaletteAnimationDestinations[slot] = &PALETTE_RAM[*data++][1];
    gPaletteAnimationFrameCounts[slot] = *data++;
    gPaletteAnimationFrameIds[slot] = data;
    data += gPaletteAnimationFrameCounts[slot];
    gPaletteAnimationTimers[slot] = 0;
    return data;
}

/**
 * @brief 按资源组加载最多两个装饰图形槽和调色板
 *
 * @address 0x08009BF0
 */
void FieldAnim_LoadResources(u8 groupId)
{
    if (groupId != 0)
    {
        const struct FieldAnimationResource *resource = gFieldAnimationResourceGroups[(u8)(groupId - 1)];
        u8 i = 0;


        for (; i < 2; resource++, i++)
        {
            if (resource->graphicsId != 0xFF)
            {
                gFieldAnimationBaseTiles[i] = resource->baseTileIndex;
                gFieldAnimationIds[i] = resource->animationId;
                LZ77UnCompVram((void *)(gFieldAnimationGraphics[resource->graphicsId]), OBJ_GRAPHICS[resource->baseTileIndex]);
                DmaCopy(3, gFieldAnimationPalettes[resource->paletteId],
                                            OBJ_PALETTE_BANK_12[i], sizeof(gFieldAnimationPalettes[0]), 16);
            }
        }
    }
}

/**
 * @brief 初始化场景装饰动画实例的位置、属性和时间线
 *
 * @address 0x08009C84
 */
void FieldAnim_InitInstances(u8 groupId)
{
    struct FieldAnimationState *animation;
    const u16 *data;
    u16 remaining;
    u8 resourceSlot;

    if (groupId != 0)
    {
        groupId--;
        animation = gFieldAnimationStates;
        data = (const u16 *)gFieldAnimationInstanceGroups[groupId];
        remaining = *data++;
        while (remaining != 0)
        {
            resourceSlot = *data;
            animation->attr2Bits = *data & 0xFF00;
            data++;
            animation->x = *data++;
            animation->y = *data++;
            animation->verticalOffset = *data++;
            animation->baseTileIndex = gFieldAnimationBaseTiles[resourceSlot];
            animation->paletteBank = resourceSlot + 12;
            animation->animationData = gFieldAnimationData[gFieldAnimationIds[resourceSlot]];
            animation->enabled = 1;
            animation->animationTimer = 0;
            animation->spriteSlot = 0;
            animation->stateFlags = 0;
            remaining--;
            animation++;
        }
    }
}

#if 0 /* Nonmatching C retained for future matching. */
/**
 * @brief 推进并绘制场景装饰动画，记录精灵链的可见状态
 *
 * @note 菜单打开时跳过；计时为零时先建立初始帧，整链不可见时暂停后续推进但仍提交绘制。
 * @address 0x08009D34
 */
void FieldAnim_Update(void)
{
    struct FieldAnimationState *animation;
    s16 instance;
    const u8 *data;
    const u8 *keyframes;
    u16 duration;
    u16 remaining;
    u16 spriteSlot;

    if (gMenuState != 0)
        return;

    animation = gFieldAnimationStates;
    for (instance = 0; instance < CORE_FIELD_ANIMATION_COUNT; animation++, instance++)
    {
        if (animation->enabled != 0)
        {
            data = animation->animationData;
            if (animation->animationTimer != 0xFF)
            {
                keyframes = data + (data[2] + (data[3] << 8));
                if (animation->animationTimer == 0)
                {
                    keyframes = data + data[keyframes[8] * 2 + 8] + 4;
                    FieldAnim_BuildSpriteChain(instance, keyframes);
                    animation->animationTimer++;
                }
                else if ((u8)(animation->stateFlags & 8) == 0)
                {
                    duration = keyframes[2] | (keyframes[3] << 8);
                    remaining = keyframes[6] | (keyframes[7] << 8);
                    keyframes += 8;
                    if (animation->animationTimer >= duration)
                        animation->animationTimer = 0;
                    spriteSlot = animation->spriteSlot;
                    while (remaining != 0)
                    {
                        if (animation->animationTimer == keyframes[2] + (keyframes[3] << 8)
                            || animation->animationTimer == 0)
                        {
                            struct SpriteNode *node = &gSpriteNodes[spriteSlot];
                            struct SpriteNode *next;
                            const u8 *frame;
                            u8 frameId;

                            node->chainInfo = 0;
                            next = node->next;
                            while (next != NULL)
                            {
                                node->next = NULL;
                                node = next;
                                node->chainInfo = 0;
                                next = node->next;
                            }
                            if (animation->animationTimer == 0)
                                frameId = keyframes[0];
                            else
                                frameId = keyframes[4];
                            frame = data + data[frameId * 2 + 8];
                            FieldAnim_BuildSpriteChain(instance, frame + 4);
                            break;
                        }
                        keyframes += 4;
                        remaining--;
                    }
                    if (animation->animationTimer != 0xFF)
                        animation->animationTimer++;
                }
            }
            if (Sprite_QueueChain((u16)animation->x, (u16)animation->y, animation->spriteSlot,
                                  (u16)animation->verticalOffset, 3) != 0)
                animation->stateFlags |= 8;
            else
                animation->stateFlags &= ~8;
        }
    }
}

#else
INCLUDE_ASM("asm/nonmatchings/core", FieldAnim_Update);
#endif

/**
 * @brief 解析一帧六字节子精灵记录并建立装饰精灵链
 *
 * @address 0x08009E80
 */
void FieldAnim_BuildSpriteChain(u8 instanceId, const u8 *frame)
{
    struct FieldAnimationState *animation = &gFieldAnimationStates[instanceId];
    u8 offset = frame[0] * sizeof(struct SpriteFramePart) + 4;
    u8 remaining = frame[2];
    struct SpriteNode *node;
    struct SpriteNode *next;
    u16 baseTile;
    u16 attr0;
    u16 attr1;
    u16 attr2;
    u16 tile;
    u16 y;

    animation->spriteSlot = Sprite_FindFreeNode();
    node = &gSpriteNodes[animation->spriteSlot];
    baseTile = animation->baseTileIndex;
    frame += offset;
    while (remaining != 0)
    {
        tile = frame[4];
        y = frame[0];
        attr0 = frame[1] << 8;
        attr1 = frame[2] | (frame[3] << 8);
        node->xOffset = attr1 & 0x1FF;
        attr0 |= y;
        node->yOffset = y;
        attr2 = (animation->paletteBank << 12) | animation->attr2Bits | (tile + baseTile);
        next = Sprite_InitNode(node, remaining, attr0, attr1, attr2);
        if (node->xOffset > 255)
            node->xOffset--;
        node = next;
        frame += sizeof(struct SpriteFramePart);
        remaining--;
    }
}

/**
 * @brief 仅清三个装饰实例的启用字节
 *
 * @note 仅清三个实例的启用字节。
 * @address 0x08009F48
 */
void FieldAnim_DisableAll(void)
{
    s16 instance = 0;
    for (; instance < CORE_FIELD_ANIMATION_COUNT; instance++)
        gFieldAnimationStates[instance].enabled = 0;
}

